const FA_AIDOC_VIEWER_HTML = "<!doctype html>\n<html lang=\"zh-Hant\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>AIDoc</title>\n<style>\n:root{--bg:#fff;--fg:#1f2328;--mut:#656d76;--bd:#d0d7de;--ac:#0969da;--sf:#f6f8fa;--hl:#fff8c5;--ok:#1a7f37;--er:#cf222e;--ai:#8250df}\n@media (prefers-color-scheme:dark){:root{--bg:#0d1117;--fg:#e6edf3;--mut:#8b949e;--bd:#30363d;--ac:#58a6ff;--sf:#161b22;--hl:#3b2e00;--ok:#3fb950;--er:#f85149;--ai:#d2a8ff}}\n*{box-sizing:border-box}html,body{height:100%}body{margin:0;background:var(--bg);color:var(--fg);font:13.5px/1.55 -apple-system,\"Segoe UI\",\"Noto Sans TC\",sans-serif;display:flex;flex-direction:column}\nheader{display:flex;align-items:center;gap:10px;padding:6px 12px;border-bottom:1px solid var(--bd);background:var(--sf);flex-wrap:wrap}\nheader b{font-size:14px;word-break:break-all}.badge{padding:0 8px;border-radius:10px;border:1px solid var(--bd);font-size:12px;color:var(--mut)}.badge.ok{color:var(--ok);border-color:var(--ok)}.badge.ai{color:var(--ai);border-color:var(--ai)}\nheader .sp{flex:1}\nbutton{font:inherit;padding:3px 10px;border:1px solid var(--bd);background:var(--bg);color:var(--fg);border-radius:6px;cursor:pointer}button:hover{border-color:var(--ac)}button.p{background:var(--ac);border-color:var(--ac);color:#fff}button.ai{border-color:var(--ai);color:var(--ai)}button:disabled{opacity:.5;cursor:default}\n#app{flex:1;display:flex;min-height:0}\n#nav{width:270px;border-right:1px solid var(--bd);display:flex;flex-direction:column;background:var(--sf);min-height:0}\n#tabs{display:flex;gap:3px;padding:6px}#tabs button{flex:1;padding:3px 0}#tabs button.on{border-color:var(--ac);color:var(--ac);font-weight:600}\n#sq{margin:0 6px 6px;padding:5px 8px;border:1px solid var(--bd);border-radius:6px;background:var(--bg);color:var(--fg)}\n#list{flex:1;overflow:auto;padding:0 4px 10px}#list a,#list summary{display:block;padding:2px 6px;border-radius:5px;color:var(--fg);cursor:pointer;word-break:break-all}#list a:hover,#list summary:hover{background:var(--bd)}#list .k{color:var(--mut);font-size:11px;margin-left:6px}#list details>div{margin-left:10px}\n#main{flex:1;overflow:auto;padding:14px 20px 60px;min-width:0}\n#chat{width:360px;border-left:1px solid var(--bd);display:flex;flex-direction:column;min-height:0;background:var(--bg)}\n#msgs{flex:1;overflow:auto;padding:8px}\n.msg{margin:8px 0;padding:8px 10px;border-radius:8px;border:1px solid var(--bd);word-break:break-word}.msg.u{background:var(--sf);margin-left:24px}.msg.a{margin-right:8px}.msg.ai{border-color:var(--ai)}\n.msg .h{font-size:11px;color:var(--mut);margin-bottom:3px}.msg .acts{margin-top:6px;display:flex;gap:6px;flex-wrap:wrap}\n#qbar{display:flex;gap:6px;padding:8px;border-top:1px solid var(--bd)}#q{flex:1;padding:6px 8px;border:1px solid var(--bd);border-radius:6px;background:var(--bg);color:var(--fg)}\ndetails#net{border-top:1px solid var(--bd);padding:4px 8px;font-size:11px;color:var(--mut)}#netlog{max-height:90px;overflow:auto;font-family:ui-monospace,Consolas,monospace}\nh1.t{font-size:19px;margin:0 0 6px;word-break:break-all}h2{font-size:15px;margin:18px 0 6px;border-bottom:1px solid var(--bd);padding-bottom:3px}h3{font-size:14px;margin:12px 0 4px}\n.mut{color:var(--mut)}code,pre{font-family:ui-monospace,Consolas,monospace;font-size:12px}pre{background:var(--sf);border:1px solid var(--bd);border-radius:6px;padding:8px 10px;overflow:auto;margin:6px 0}:not(pre)>code{background:var(--sf);border:1px solid var(--bd);border-radius:4px;padding:0 4px}\na.l,.md a{color:var(--ac);cursor:pointer;text-decoration:none}a.l:hover,.md a:hover{text-decoration:underline}\ntable{border-collapse:collapse;width:100%;margin:6px 0}td,th{border-bottom:1px solid var(--bd);padding:3px 8px;text-align:left;vertical-align:top;word-break:break-word}th{background:var(--sf)}\n.tag{display:inline-block;padding:0 7px;border-radius:10px;background:var(--sf);border:1px solid var(--bd);font-size:11px;color:var(--mut);margin-right:4px}\n.note{background:var(--hl);border-radius:6px;padding:6px 10px;margin:8px 0}.err{color:var(--er)}\n.chips{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0}.chips span{padding:2px 10px;border:1px solid var(--bd);border-radius:12px;cursor:pointer;font-size:12px}.chips span:hover{border-color:var(--ac);color:var(--ac)}.chips span.ai{border-color:var(--ai);color:var(--ai)}\n.md ul,.md ol{padding-left:20px}.md blockquote{border-left:3px solid var(--bd);margin:6px 0;padding:0 10px;color:var(--mut)}\nsvg.dg{max-width:100%;height:auto;background:var(--sf);border:1px solid var(--bd);border-radius:6px}svg.dg text{fill:var(--fg);font:12px sans-serif}svg.dg rect{fill:var(--bg);stroke:var(--ac)}svg.dg path{stroke:var(--mut);fill:none}\n#top{flex:1;display:flex;min-width:0;min-height:0}\n#nav{width:var(--navw,270px);flex:none}#chat{width:var(--chatw,360px);flex:none}\n.sp{flex:none;background:var(--bd);opacity:.45;z-index:2;touch-action:none}.sp:hover,.sp.drag{background:var(--ac);opacity:1}\n#spL{width:5px;cursor:col-resize}#spR{width:5px;cursor:col-resize}\n#app.dock-left{flex-direction:row-reverse}#app.dock-left #chat{border-left:0;border-right:1px solid var(--bd)}\n#app.dock-bottom{flex-direction:column}#app.dock-bottom #spR{width:auto;height:5px;cursor:row-resize}#app.dock-bottom #chat{width:auto;height:var(--chath,38%);border-left:0;border-top:1px solid var(--bd)}\nbody.hide-nav #nav,body.hide-nav #spL,body.hide-chat #chat,body.hide-chat #spR{display:none}\n#btnNav.off,#btnChat.off{opacity:.5}\n@media (max-width:900px){#chat{width:var(--chatw,300px)}#nav{width:var(--navw,200px)}}\n@media (max-width:640px){#top{flex-direction:column}#nav{width:100%;max-height:34vh;border:0;border-bottom:1px solid var(--bd)}#app.dock-right,#app.dock-left{flex-direction:column}#app.dock-right #chat,#app.dock-left #chat{width:100%;max-height:40vh}#spL,#spR{display:none}}\n.loc{border-bottom:1px dashed var(--ac)}.loccard{margin:6px 0 10px;border:1px solid var(--ac);border-radius:8px;background:var(--sf);overflow:hidden}.loccard .lh{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:6px 10px;border-bottom:1px solid var(--bd);font-weight:600}.loccard .lh .x{margin-left:auto;cursor:pointer;color:var(--mut)}.loccard .lb{padding:6px 10px}.loccard pre{margin:6px 0;padding:0;border:none;background:none;overflow:auto;max-height:340px}.loccard .cl{display:block;white-space:pre;padding:0 8px}.loccard .cl i{display:inline-block;width:3.2em;color:var(--mut);font-style:normal;text-align:right;margin-right:8px;user-select:none}.loccard .cl.hit{background:var(--hl)}.loccard .acts{display:flex;gap:6px;flex-wrap:wrap;margin:6px 0}\n.loccard .vp{margin:6px 0;border:1px solid var(--bd);border-radius:6px;overflow:hidden;background:var(--bg)}.loccard .vp .vbar{padding:2px 8px;background:var(--sf);font-size:12px;color:var(--mut)}.loccard .vp .vbar.top{border-bottom:1px solid var(--bd)}.loccard .vp .vbar.bot{border-top:1px solid var(--bd)}.loccard .vp .more{padding:1px 8px;font-size:12px}.loccard .vp pre.vpre{margin:0;max-height:300px;border:none;border-radius:0}\n.mde{border:1px solid var(--ac);border-radius:8px;margin:8px 0;background:var(--bg);overflow:hidden}.mde .tb{display:flex;gap:4px;flex-wrap:wrap;padding:5px 8px;background:var(--sf);border-bottom:1px solid var(--bd);align-items:center}.mde .tb button{padding:1px 8px;font-size:12px}.mde .tb .sp{flex:1}.mde .pn{display:grid;grid-template-columns:1fr 1fr;min-height:200px}.mde textarea{width:100%;min-height:200px;max-height:60vh;resize:vertical;border:none;border-right:1px solid var(--bd);padding:8px;font:12.5px/1.5 ui-monospace,Consolas,monospace;background:var(--bg);color:var(--fg);outline:none}.mde .pv{padding:6px 10px;overflow:auto;max-height:60vh}.mde .ft{display:flex;gap:8px;align-items:center;padding:6px 8px;border-top:1px solid var(--bd);background:var(--sf)}@media(max-width:760px){.mde .pn{grid-template-columns:1fr}.mde textarea{border-right:none;border-bottom:1px solid var(--bd)}}\n.nvb{padding:2px 9px;border:1px solid var(--bd);border-radius:6px;background:var(--bg);color:var(--fg);cursor:pointer}.nvb:disabled{opacity:.35;cursor:default}\n#navp{position:fixed;top:42px;left:8px;z-index:60;width:min(460px,92vw);max-height:62vh;overflow:auto;background:var(--bg);border:1px solid var(--bd);border-radius:8px;box-shadow:0 6px 22px rgba(0,0,0,.25);padding:4px;display:none}\n#navp .nh{display:flex;align-items:center;gap:8px;padding:4px 8px;color:var(--mut);font-size:12px}#navp .nh b{flex:1}\n#navp a{display:flex;gap:8px;align-items:baseline;padding:4px 8px;border-radius:5px;cursor:pointer;color:var(--fg);word-break:break-all;text-decoration:none}#navp a:hover{background:var(--sf)}\n#navp a.cur{background:var(--hl);font-weight:600}#navp a.fail{color:var(--er)}#navp a .ix{color:var(--mut);font-size:11px;min-width:22px;text-align:right}\n</style></head><body>\n<header><button class=\"nvb\" id=\"navB\" title=\"上一個位置（Alt+←、滑鼠上一頁鍵）\" disabled>◀</button><button class=\"nvb\" id=\"navF\" title=\"下一個位置（Alt+→、滑鼠下一頁鍵）\" disabled>▶</button><button class=\"nvb\" id=\"navH\" title=\"瀏覽歷史（像 call stack：最新在最上面，點一下跳回去）\">🕘</button><b id=\"ttl\">AIDoc</b><span class=\"badge\" id=\"stat\">載入中…</span><span class=\"badge\" id=\"jobs\" style=\"display:none\"></span><span class=\"sp\"></span><span class=\"badge ai\" id=\"aiq\" style=\"display:none\"></span><button id=\"btnNav\" title=\"顯示／隱藏左邊（瀏覽）\">◧</button><button id=\"btnChat\" title=\"顯示／隱藏右邊（問答）\">◨</button><select id=\"dockSel\" title=\"右邊問答區停靠的位置\"><option value=\"right\">右邊在右</option><option value=\"left\">右邊改到左</option><option value=\"bottom\">右邊改到下</option></select><button id=\"btnReset\" title=\"把版面（寬度、停靠位置、顯示隱藏）和視窗位置大小都還原成預設\">還原版面</button><button id=\"btnNet\" title=\"這個畫面用假的 fetch／WebSocket 跟主程式溝通\">🔌 連線 <span id=\"wsdot\">●</span></button></header>\n<div id=\"app\" class=\"dock-right\"><div id=\"top\">\n<aside id=\"nav\"><div id=\"tabs\"><button data-t=\"pages\" class=\"on\">頁面</button><button data-t=\"tree\">檔案</button><button data-t=\"syms\">定義</button><button data-t=\"notes\">說明</button></div><input id=\"sq\" placeholder=\"搜尋…（語意搜尋）\"><div id=\"list\"></div></aside><div class=\"sp\" id=\"spL\" title=\"拖曳調整左邊寬度（雙擊還原）\"></div>\n<main id=\"main\"><div class=\"mut\">載入中…</div></main></div>\n<div class=\"sp\" id=\"spR\" title=\"拖曳調整右邊（雙擊還原）\"></div>\n<section id=\"chat\"><div id=\"msgs\"></div><div id=\"qbar\"><input id=\"q\" placeholder=\"問這個專案：某函式做什麼／在哪定義／誰用到…\" autofocus><button id=\"ask\" class=\"p\" title=\"離線問答（立刻回答）\">問</button><button id=\"askai\" class=\"ai\" title=\"請 AI 讀程式碼後回答（依序處理，AI 在背景參與）\">問 AI</button></div>\n<details id=\"net\"><summary>通訊紀錄（fetch／WebSocket）</summary><div id=\"netlog\"></div></details></section>\n</div>\n<script id=\"cfg\" type=\"application/json\">__CFG__</script>\n__SHIM__\n<script>\n(function(){\nvar CFG=JSON.parse(document.getElementById('cfg').textContent);\nfunction $(s){return document.querySelector(s)}\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]})}\nvar PATHRE=/^[\\w.+\\-@\\/]+\\.[A-Za-z0-9]{1,6}(:\\d+(-\\d+)?)?$/,SYMRE=/^[A-Za-z_][\\w:.]{2,}$/;\nvar BASE='http://mock.local';\nvar NET=[];\nfunction netlog(t){NET.push(new Date().toLocaleTimeString()+'  '+t);if(NET.length>60)NET.shift();var el=$('#netlog');if(el){el.textContent=NET.join('\\n');el.scrollTop=1e9}}\nasync function api(method,path,body){\n  var t0=performance.now();\n  var r=await fetch(BASE+path,{method:method,headers:{'content-type':'application/json'},body:body?JSON.stringify(body):undefined});\n  var j=null;try{j=await r.json()}catch(e){j={error:'回應不是JSON'}}\n  netlog(method+' '+path.slice(0,70)+' → '+r.status+'  '+Math.round(performance.now()-t0)+'ms');\n  if(!r.ok)throw new Error((j&&j.error)||('HTTP '+r.status));\n  return j;\n}\nfunction mdToHtml(src){\n  var s=String(src==null?'':src).replace(/\\r/g,'');\n  var blocks=[];\n  s=s.replace(/```[^\\n]*\\n([\\s\\S]*?)```/g,function(_,c){blocks.push('<pre>'+esc(c.replace(/\\n$/,''))+'</pre>');return '\\u0000'+(blocks.length-1)+'\\u0000'});\n  var lines=s.split('\\n'),out=[],list=null;\n  (function(){ /* 表格：下一行是 |---|---| 分隔線就當表格；補齊左右的 |，表頭做成 th */\n    var SEP=/^\\s*\\|?\\s*:?-{2,}:?\\s*(\\|\\s*:?-{2,}:?\\s*)*\\|?\\s*$/;\n    for(var i=0;i<lines.length-1;i++){\n      if(lines[i].indexOf('|')<0||lines[i+1].indexOf('|')<0||!SEP.test(lines[i+1])||/^\\u0000/.test(lines[i].trim()))continue;\n      var j=i;\n      while(j<lines.length&&lines[j].trim()&&lines[j].indexOf('|')>=0){var x=lines[j].trim();if(x.charAt(0)!=='|')x='|'+x;if(x.charAt(x.length-1)!=='|'||/\\\\\\|$/.test(x))x+='|';lines[j]=(j===i?'\\u0002':'')+x;j++}\n      i=j-1;\n    }\n  })();\n  function inl(t){\n    t=esc(t);\n    t=t.replace(/`([^`]+)`/g,function(_,c){\n      var raw=c.replace(/&amp;/g,'&');\n      if(/^[\\w.+\\-@\\/]+\\/$/.test(raw))return '<a class=\"l\" data-go=\"dir:'+esc(raw.replace(/\\/+$/,''))+'\"><code>'+c+'</code></a>';\n      var lm=/^(.+?):(\\d+)(?:-(\\d+))?$/.exec(raw);\n      if(PATHRE.test(raw)&&lm)return locLink(lm[1],lm[2],lm[3],'<code>'+c+'</code>');\n      if(PATHRE.test(raw))return '<a class=\"l\" data-go=\"file:'+esc(raw)+'\"><code>'+c+'</code></a>';\n      if(SYMRE.test(raw)&&!/^\\d/.test(raw))return '<a class=\"l\" data-go=\"sym:'+esc(raw)+'\"><code>'+c+'</code></a>';\n      return '<code>'+c+'</code>'});\n    var keep=[];t=t.replace(/<a [^>]*>.*?<\\/a>|<code>.*?<\\/code>/g,function(m){keep.push(m);return '\\u0001'+(keep.length-1)+'\\u0001'});\n    t=t.replace(/(^|[^\\w\\/.\\-])((?:[\\w.+\\-\\x40]+\\/)*[\\w.+\\-\\x40]+\\.[A-Za-z][A-Za-z0-9]{0,5}):(\\d+)(?:-(\\d+))?(?![\\d\\w])/g,function(_,pre,pth,ln,to){return pre+locLink(pth,ln,to,esc(pth+':'+ln+(to?'-'+to:'')))});\n    t=t.replace(/\\u0001(\\d+)\\u0001/g,function(_,n){return keep[+n]});\n    t=t.replace(/\\*\\*([^*]+)\\*\\*/g,'<b>$1</b>');\n    return t;\n  }\n  function close(){if(list){out.push('</'+list+'>');list=null}}\n  lines.forEach(function(l){\n    var m;\n    if(/^\\u0000\\d+\\u0000$/.test(l.trim())){close();out.push(blocks[+l.trim().replace(/\\u0000/g,'')]);return}\n    if((m=/^\\s*<details( open)?><summary>(.*)<\\/summary>\\s*$/.exec(l))){close();out.push('<details'+(m[1]||'')+'><summary>'+inl(m[2].replace(/<[^>]+>/g,'').replace(/&lt;/g,'<').replace(/&gt;/g,'>'))+'</summary>');return}\n    if(/^\\s*<\\/details>\\s*$/.test(l)){close();out.push('</details>');return}\n    if((m=/^(#{1,4})\\s+(.*)$/.exec(l))){close();var n=Math.min(3,m[1].length+1);out.push('<h'+n+'>'+inl(m[2])+'</h'+n+'>');return}\n    if((m=/^\\s*[-*]\\s+(.*)$/.exec(l))){if(list!=='ul'){close();out.push('<ul>');list='ul'}out.push('<li>'+inl(m[1])+'</li>');return}\n    if((m=/^\\s*\\d+[.)]\\s+(.*)$/.exec(l))){if(list!=='ol'){close();out.push('<ol>');list='ol'}out.push('<li>'+inl(m[1])+'</li>');return}\n    if((m=/^>\\s?(.*)$/.exec(l))){close();out.push('<blockquote>'+inl(m[1])+'</blockquote>');return}\n    if(/^\\u0002?\\|.*\\|\\s*$/.test(l)){close();var hd=l.charAt(0)==='\\u0002';if(hd)l=l.slice(1);if(/^\\|[\\s:|-]+\\|$/.test(l.trim())&&/-/.test(l))return;var cells=l.trim().slice(1,-1).split(/(?<!\\\\)\\|/);var tg=hd?'th':'td';out.push('<table><tr>'+cells.map(function(c){return '<'+tg+'>'+inl(c.trim().replace(/\\\\\\|/g,'|'))+'</'+tg+'>'}).join('')+'</tr></table>');return}\n    close();\n    if(!l.trim())return;\n    out.push('<p>'+inl(l)+'</p>');\n  });\n  close();\n  return out.join('\\n').replace(/<\\/table>\\n<table>/g,'');\n}\n\nvar ws=null,wsTry=0;\nfunction connect(){\n  try{ws=new WebSocket('ws://mock.local/ws')}catch(e){netlog('WebSocket 建立失敗：'+e.message);return}\n  ws.onopen=function(){wsTry=0;$('#wsdot').style.color='var(--ok)';netlog('WS open /ws');ws.send(JSON.stringify({type:'hello'}))};\n  ws.onmessage=function(ev){var m;try{m=JSON.parse(ev.data)}catch(e){return}netlog('WS ← '+m.type);onEvent(m)};\n  ws.onclose=function(){$('#wsdot').style.color='var(--er)';netlog('WS close');if(wsTry++<5)setTimeout(connect,1000*wsTry)};\n}\nvar cur={kind:'',key:''};\nvar AIB={}; // 問題id→AI訊息節點\nfunction addMsg(cls,head,html,acts){\n  var d=document.createElement('div');d.className='msg '+cls;\n  d.innerHTML='<div class=\"h\">'+esc(head)+'</div><div class=\"b md\">'+html+'</div>';\n  if(acts&&acts.length){var a=document.createElement('div');a.className='acts';acts.forEach(function(x){var b=document.createElement('button');b.textContent=x[0];if(x[2])b.className=x[2];b.onclick=function(){x[1](b)};a.appendChild(b)});d.appendChild(a)}\n  $('#msgs').appendChild(d);$('#msgs').scrollTop=1e9;return d;\n}\nasync function ask(q,ctx,ai){\n  q=String(q||'').trim();if(!q)return;\n  addMsg('u',ai?'你（請 AI 回答）':'你',esc(q));\n  try{\n    var r=await api('POST','/api/ask',{q:q,ctx:ctx||cur,ai:!!ai});\n    var acts=[];\n    if(!ai)acts.push(['請 AI 深入回答',function(b){b.disabled=true;ask(q,ctx,true)},'ai']);\n    addMsg('a','離線問答（'+esc(r.quick.intent)+'）',mdToHtml(r.quick.answer||'（沒有結果）'),acts);\n    if(r.ai_id){var n=addMsg('a ai','AI（'+(r.queue_pos>1?'排隊中，前面還有 '+(r.queue_pos-1)+' 個':'準備中')+'）','<span class=\"mut\">⏳ 等待…</span>');AIB[r.ai_id]={node:n,q:q,ctx:ctx||cur}}\n  }catch(e){addMsg('a','錯誤','<span class=\"err\">'+esc(e.message)+'</span>')}\n}\nfunction chips(list){return '<div class=\"chips\">'+list.map(function(c,i){return '<span data-ci=\"'+i+'\" class=\"'+(c[2]||'')+'\">'+esc(c[0])+'</span>'}).join('')+'</div>'}\nfunction wireChips(root,list){root.querySelectorAll('.chips span').forEach(function(sp){sp.onclick=function(){var c=list[+sp.dataset.ci];ask(c[1],cur,c[2]==='ai')}})}\nfunction onEvent(m){\n  if(m.type==='info'){setInfo(m.info)}\n  else if(m.type==='jobs'){setJobs(m.jobs)}\n  else if(m.type==='ai_queue'){var q=$('#aiq');q.style.display=m.n?'':'none';q.textContent='🤖 AI 佇列 '+m.n}\n  else if(m.type==='ai_start'){var b=AIB[m.id];if(b)b.node.querySelector('.h').textContent='AI（讀程式碼中…）'}\n  else if(m.type==='ai_progress'){var b2=AIB[m.id];if(b2)b2.node.querySelector('.b').innerHTML='<span class=\"mut\">⏳ '+esc(m.text)+'</span>'}\n  else if(m.type==='ai_answer'){var b3=AIB[m.id];if(b3){b3.node.querySelector('.h').textContent='AI 回答';b3.node.querySelector('.b').innerHTML=mdToHtml(m.text||'（沒有回答）');if(m.notes_changed){var a=document.createElement('div');a.className='mut';a.textContent='✅ AI 已把確認過的說明補進資料庫';b3.node.appendChild(a)}else if(cur.kind==='file'||cur.kind==='symbol'){var ac=document.createElement('div');ac.className='acts';var bt=document.createElement('button');bt.textContent='把這段存成說明';bt.onclick=function(){saveNote(b3.ctx||cur,m.text,bt)};ac.appendChild(bt);b3.node.appendChild(ac)}}}\n  else if(m.type==='notes_changed'){refreshCur()}\n}\nasync function saveNote(ctx,text,btn){try{await api('POST','/api/note',{path:ctx.path,symbol:ctx.kind==='symbol'?ctx.name:undefined,note:String(text).replace(/\\r/g,'').split('\\n').map(function(l){return l.replace(/[ \\t]+/g,' ').trimEnd()}).join('\\n').replace(/\\n{3,}/g,'\\n\\n').trim().slice(0,2000)});if(btn){btn.textContent='✅ 已存入';btn.disabled=true}}catch(e){alert('存入失敗：'+e.message)}}\nfunction setInfo(i){CFG.info=i;$('#ttl').textContent=i.title||CFG.title;$('#stat').textContent=i.files+' 個檔案 · '+i.symbols+' 個定義 · 說明 '+(i.notes_files+i.notes_symbols)+(i.complete?'':' · 部分索引');$('#stat').className='badge'+(i.complete?' ok':'')}\nfunction setJobs(j){var el=$('#jobs');var t=[];if(j.index&&j.index.running)t.push('索引 '+j.index.percent+'%');if(j.dive&&j.dive.running)t.push('深入探討 '+j.dive.done+'/'+j.dive.total);el.style.display=t.length?'':'none';el.textContent='⏳ '+t.join('・')}\n/* ---- 導覽 ---- */\nvar tab='pages';\nasync function renderList(){\n  var q=$('#sq').value.trim(),h='';\n  try{\n    if(q.length>=2){var r=await api('GET','/api/search?q='+encodeURIComponent(q));h=r.hits.map(function(x){return x.type==='symbol'?'<a data-go=\"sym:'+esc(x.name)+'\">'+esc(x.name)+'<span class=\"k\">'+esc(x.kind)+' · '+esc(x.path)+':'+x.line+'</span></a>':'<a data-go=\"file:'+esc(x.path)+'\">'+esc(x.path)+'<span class=\"k\">檔案</span></a>'}).join('')||'<div class=\"mut\" style=\"padding:6px\">沒有結果</div>'}\n    else if(tab==='pages'){var p=await api('GET','/api/pages');h=p.pages.map(function(x){return '<a data-go=\"page:'+esc(x.id)+'\">'+esc(x.title)+(x.auto?'<span class=\"k\">草稿</span>':'')+'</a>'}).join('')||'<div class=\"mut\" style=\"padding:6px\">還沒有百科頁面（/deepwiki wiki 產生）</div>'}\n    else if(tab==='tree'){h='<div id=\"tr\"></div>';$('#list').innerHTML=h;await loadTree('',$('#tr'));return}\n    else if(tab==='syms'){var s=await api('GET','/api/symbols');h=s.symbols.map(function(x){return '<a data-go=\"sym:'+esc(x.name)+'\">'+esc(x.name)+'<span class=\"k\">'+esc(x.kind)+'</span></a>'}).join('')}\n    else{var n=await api('GET','/api/notes');h=n.notes.map(function(x){return '<a data-go=\"'+(x.symbol?'sym:'+esc(x.symbol):'file:'+esc(x.path))+'\">'+esc(x.symbol||x.path)+'<span class=\"k\">'+esc(x.by||'')+(x.stale?' · 可能過期':'')+'</span></a>'}).join('')||'<div class=\"mut\" style=\"padding:6px\">還沒有說明。AI 深入探討或你自己補的說明會出現在這裡。</div>'}\n  }catch(e){h='<div class=\"err\" style=\"padding:6px\">'+esc(e.message)+'</div>'}\n  $('#list').innerHTML=h;\n}\nasync function loadTree(path,host){\n  var r=await api('GET','/api/tree?path='+encodeURIComponent(path));\n  var h='';r.dirs.forEach(function(d){var p=path?path+'/'+d:d;h+='<details data-p=\"'+esc(p)+'\"><summary>'+esc(d)+'/</summary><div></div></details>'});\n  r.files.forEach(function(f){var p=path?path+'/'+f.name:f.name;h+='<a data-go=\"file:'+esc(p)+'\">'+esc(f.name)+(f.note?'<span class=\"k\">✎</span>':'')+'</a>'});\n  if(r.more)h+='<div class=\"mut\" style=\"padding:2px 6px\">…另有 '+r.more+' 項</div>';\n  host.innerHTML=h;\n  host.querySelectorAll('details').forEach(function(dt){dt.addEventListener('toggle',function(){if(dt.open&&!dt.dataset.loaded){dt.dataset.loaded=1;loadTree(dt.dataset.p,dt.querySelector('div'))}})});\n}\nfunction noteFold(x){x=String(x==null?'':x).trim();if(!x)return '';var multi=x.length>220||x.indexOf('\\n')>=0;if(!multi)return '<div class=\"md\">'+mdToHtml(x)+'</div>';var first=(x.split('\\n').filter(function(l){return l.trim()})[0]||'').replace(/^#+\\s*/,'').replace(/[*`|]/g,'').trim().slice(0,100);return '<details><summary>'+esc(first||'說明')+'</summary><div class=\"md\">'+mdToHtml(x)+'</div></details>'}\nfunction noteHtml(x){x=String(x==null?'':x);return /\\n|\\|.*\\|/.test(x)?'<div class=\"md\">'+mdToHtml(x)+'</div>':esc(x)}\nfunction mdEditor(opt){\n  /* Markdown 編輯器：工具列（標題、粗體、行內碼、程式碼區塊、清單、表格、引用）＋左右即時預覽；Tab 縮排、Ctrl+Enter 存檔、Esc 取消 */\n  var MAX=2000,box=document.createElement('div');box.className='mde';\n  box.innerHTML='<div class=\"tb\"><b>'+esc(opt.title||'編輯說明')+'</b><button data-k=\"h\">H</button><button data-k=\"b\"><b>B</b></button><button data-k=\"c\">`code`</button><button data-k=\"cb\">```</button><button data-k=\"ul\">• 清單</button><button data-k=\"ol\">1. 清單</button><button data-k=\"tbl\">▦ 表格</button><button data-k=\"q\">❝ 引用</button><span class=\"sp\"></span><span class=\"mut\">Markdown，右邊即時預覽</span></div><div class=\"pn\"><textarea spellcheck=\"false\"></textarea><div class=\"pv md\"></div></div><div class=\"ft\"><button class=\"p\" data-k=\"save\">存起來</button><button data-k=\"cancel\">取消</button><span class=\"mut cnt\"></span></div>';\n  var ta=box.querySelector('textarea'),pv=box.querySelector('.pv'),cnt=box.querySelector('.cnt');\n  ta.value=opt.value||'';\n  var tm=null;function upd(){cnt.textContent=ta.value.length+' / '+MAX+(ta.value.length>MAX?'（超過的部分不會存）':'');cnt.style.color=ta.value.length>MAX?'var(--er)':'';clearTimeout(tm);tm=setTimeout(function(){pv.innerHTML=ta.value.trim()?mdToHtml(ta.value):'<span class=\"mut\">（預覽）</span>'},120)}\n  function wrap(a,b,ph){var s=ta.selectionStart,e=ta.selectionEnd,v=ta.value,sel=v.slice(s,e)||ph||'';ta.value=v.slice(0,s)+a+sel+b+v.slice(e);ta.focus();ta.selectionStart=s+a.length;ta.selectionEnd=s+a.length+sel.length;upd()}\n  function lines(prefix){var s=ta.selectionStart,e=ta.selectionEnd,v=ta.value,ls=v.lastIndexOf('\\n',s-1)+1,le=v.indexOf('\\n',e);if(le<0)le=v.length;var blk=v.slice(ls,le).split('\\n').map(function(l,i){return typeof prefix==='function'?prefix(i)+l:prefix+l}).join('\\n');ta.value=v.slice(0,ls)+blk+v.slice(le);ta.focus();ta.selectionStart=ls;ta.selectionEnd=ls+blk.length;upd()}\n  function insert(txt){var s=ta.selectionStart,v=ta.value,pre=s>0&&v.charAt(s-1)!=='\\n'?'\\n\\n':'';ta.value=v.slice(0,s)+pre+txt+v.slice(ta.selectionEnd);ta.focus();ta.selectionStart=ta.selectionEnd=s+pre.length+txt.length;upd()}\n  var acts={h:function(){lines('## ')},b:function(){wrap('**','**','重點')},c:function(){wrap('`','`','名稱')},cb:function(){wrap('\\n```\\n','\\n```\\n','程式碼')},ul:function(){lines('- ')},ol:function(){lines(function(i){return (i+1)+'. '})},q:function(){lines('> ')},\n    tbl:function(){insert('| 項目 | 說明 |\\n|---|---|\\n| 輸入 |  |\\n| 輸出 |  |\\n| 副作用／限制 |  |\\n')}};\n  box.querySelectorAll('.tb button').forEach(function(b){b.onclick=function(e){e.preventDefault();acts[b.dataset.k]()}});\n  ta.oninput=upd;\n  ta.onkeydown=function(e){\n    if(e.key==='Tab'){e.preventDefault();var s=ta.selectionStart;ta.value=ta.value.slice(0,s)+'  '+ta.value.slice(ta.selectionEnd);ta.selectionStart=ta.selectionEnd=s+2;upd()}\n    else if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();box.querySelector('[data-k=save]').click()}\n    else if(e.key==='Escape'){e.preventDefault();box.remove()}\n  };\n  box.querySelector('[data-k=cancel]').onclick=function(){box.remove()};\n  box.querySelector('[data-k=save]').onclick=function(){var v=ta.value;if(v.trim().length<6){alert('說明太短（至少寫一句有內容的）');return}opt.onSave(v.slice(0,MAX),box)};\n  upd();setTimeout(function(){ta.focus()},0);\n  return box;\n}\nfunction locLink(path,line,to,inner){return '<a class=\"l loc\" data-loc=\"'+esc(path)+'|'+esc(line)+'|'+esc(to||'')+'\" title=\"點一下在這裡展開該區塊的說明與程式碼\">'+inner+'</a>'}\nfunction initViewport(host,r){\n  /* 像 diff：只顯示指定的行範圍，捲到該處；上下各有「展開更多」，按下去再讀 20 行（連續按、或展開到頭尾） */\n  var lines={},from=r.from,to=r.from+r.text.split('\\n').length-1,total=r.total,STEP=20;\n  r.text.split('\\n').forEach(function(l,k){lines[r.from+k]=l});\n  host.innerHTML='<div class=\"vbar top\"></div><pre class=\"vpre\"></pre><div class=\"vbar bot\"></div>';\n  var pre=host.querySelector('.vpre'),top=host.querySelector('.top'),bot=host.querySelector('.bot');\n  function lineHtml(n){var hit=n>=r.line&&n<=Math.max(r.line,r.to);return '<span class=\"cl'+(hit?' hit':'')+'\" data-n=\"'+n+'\"><i>'+n+'</i>'+esc(lines[n])+'</span>'}\n  function bars(){\n    top.innerHTML=from>1?'<button class=\"more\" data-d=\"up\">⋯ 展開上面 '+Math.min(STEP,from-1)+' 行（上面還有 '+(from-1)+' 行）</button> <button class=\"more\" data-d=\"top\">到檔案開頭</button>':'<span class=\"mut\">檔案開頭</span>';\n    bot.innerHTML=to<total?'<button class=\"more\" data-d=\"down\">⋯ 展開下面 '+Math.min(STEP,total-to)+' 行（下面還有 '+(total-to)+' 行）</button> <button class=\"more\" data-d=\"end\">到檔案結尾</button>':'<span class=\"mut\">檔案結尾</span>';\n  }\n  function render(){var h='';for(var n=from;n<=to;n++)h+=lineHtml(n);pre.innerHTML=h;bars()}\n  function focusHit(){var el=pre.querySelector('.cl.hit');if(el)pre.scrollTop=Math.max(0,el.offsetTop-pre.clientHeight/2+el.offsetHeight/2)}\n  async function load(a,b){\n    if(a>b)return;\n    var s=await api('GET','/api/source?path='+encodeURIComponent(r.path)+'&from='+a+'&to='+b);\n    s.text.split('\\n').forEach(function(l,k){lines[s.from+k]=l});total=s.total;return s;\n  }\n  host.onclick=async function(e){\n    var b=e.target.closest('.more');if(!b)return;e.stopPropagation();\n    var d=b.dataset.d;b.disabled=true;\n    try{\n      var before=pre.scrollHeight,st=pre.scrollTop;\n      if(d==='up'||d==='top'){var a=d==='top'?1:Math.max(1,from-STEP);await load(a,from-1);from=a;render();pre.scrollTop=st+(pre.scrollHeight-before)}\n      else{var z=d==='end'?total:Math.min(total,to+STEP);await load(to+1,z);to=Math.max(to,z);render();pre.scrollTop=st}\n    }catch(err){b.textContent='失敗：'+err.message}\n  };\n  render();focusHit();\n}\nvar LOCQ=0;\nasync function toggleLoc(a){\n  var host=a.closest('p,li,td,blockquote,h1,h2,h3,div.b')||a.parentNode;\n  var ex=host.nextElementSibling;\n  var key=a.getAttribute('data-loc');\n  if(ex&&ex.classList&&ex.classList.contains('loccard')&&ex.dataset.key===key){ex.remove();return}\n  var parts=key.split('|'),path=parts[0],line=parts[1],to=parts[2];\n  var card=document.createElement('div');card.className='loccard';card.dataset.key=key;\n  card.innerHTML='<div class=\"lh\"><span>'+esc(path)+':'+esc(line)+(to?'-'+esc(to):'')+'</span><span class=\"x\" title=\"收起來\">✕</span></div><div class=\"lb mut\">讀取中…</div>';\n  card.querySelector('.x').onclick=function(){card.remove()};\n  if(ex&&ex.classList&&ex.classList.contains('loccard'))ex.remove();\n  host.parentNode.insertBefore(card,host.nextSibling);\n  try{\n    var r=await api('GET','/api/locate?path='+encodeURIComponent(path)+'&line='+encodeURIComponent(line)+(to?'&to='+encodeURIComponent(to):''));\n    var h='';\n    card.querySelector('.lh span').textContent=r.path+':'+r.line+(r.to>r.line?'-'+r.to:'');\n    var tags='<span class=\"tag\">'+esc(r.lang)+'</span>';\n    if(r.def)tags+=' <span class=\"tag\">在 '+esc(r.def.kind)+' '+esc(r.def.name)+'（第 '+r.def.line+(r.def.end?'–'+r.def.end:'')+' 行起）</span>';\n    h+='<div>'+tags+'</div>';\n    if(r.def){\n      h+=r.def.note?'<div class=\"note\"><b>說明</b>：'+noteHtml(r.def.note)+(r.def.stale?'（可能過期）':'')+'</div>':(r.def.doc?'<div class=\"note\"><b>註解</b>：'+esc(r.def.doc)+'</div>':'<div class=\"mut\">這個定義還沒有說明。</div>');\n      if(r.def.sig)h+='<div><code>'+esc(r.def.sig)+'</code></div>';\n      if(r.users.length)h+='<div class=\"mut\">被這些檔案使用：'+r.users.slice(0,8).map(function(p){return link(p)}).join('、')+(r.users.length>8?' …':'')+'</div>';\n    }else if(r.file_note||r.file_doc){h+='<div class=\"note\"><b>檔案說明</b>：'+esc(r.file_note||r.file_doc)+'</div>'}\n    else h+='<div class=\"mut\">這一行不在任何定義裡（檔案最上面或定義之間）。</div>';\n    h+=r.text!=null?'<div class=\"vp\"></div>':'<div class=\"mut\">讀不到程式碼（專案資料夾不在了？）。</div>';\n    h+='<div class=\"acts\"><button data-go=\"file:'+esc(r.path)+'\">開啟整個檔案</button>'+(r.def?'<button data-go=\"sym:'+esc(r.def.name)+'\">開啟 '+esc(r.def.name)+' 的定義頁</button><button class=\"beh\">行為說明（這個定義做了什麼）</button>':'')+'<button class=\"ai\">請 AI 解釋這一段</button></div><div class=\"behbox md\"></div>';\n    var lb=card.querySelector('.lb');lb.className='lb';lb.innerHTML=h;\n    if(r.text!=null)initViewport(lb.querySelector('.vp'),r);\n    var bb=lb.querySelector('.beh');\n    if(bb)bb.onclick=async function(){bb.disabled=true;var box=lb.querySelector('.behbox');box.innerHTML='<span class=\"mut\">分析中…</span>';try{var e=await api('GET','/api/explain?path='+encodeURIComponent(r.path)+'&fn='+encodeURIComponent(r.def.name));box.innerHTML=mdToHtml(e.markdown)}catch(err){box.innerHTML='<span class=\"err\">'+esc(err.message)+'</span>'}};\n    var ab=lb.querySelector('.ai');\n    if(ab)ab.onclick=function(){ab.disabled=true;ask('請讀 '+r.path+' 第 '+r.line+(r.to>r.line?'–'+r.to:'')+' 行附近'+(r.def?'（'+r.def.kind+' '+r.def.name+'）':'')+'，用白話解釋這一段在做什麼、為什麼這樣寫、要注意什麼',{kind:'file',key:r.path,path:r.path,name:r.path},true)};\n  }catch(e){card.querySelector('.lb').innerHTML='<span class=\"err\">'+esc(e.message)+'</span>'}\n}\nfunction link(path,label){return '<a class=\"l\" data-go=\"file:'+esc(path)+'\">'+esc(label||path)+'</a>'}\nfunction slink(n){return '<a class=\"l\" data-go=\"sym:'+esc(n)+'\">'+esc(n)+'</a>'}\nasync function showPage(id){cur={kind:'page',key:id,path:'',name:id};var r=await api('GET','/api/page?id='+encodeURIComponent(id));var cs=[['這個專案整體怎麼分層？','這個專案整體怎麼分層、主要模組有哪些'],['請 AI 用白話說明這一頁','請用白話說明這一頁（'+r.title+'）的重點，並指出最值得先看的檔案','ai']];$('#main').innerHTML='<div class=\"md\">'+(r.auto?'<div class=\"note\">這一頁是依程式碼結構自動產生的草稿。</div>':'')+mdToHtml(r.md)+'</div>'+chips(cs);wireChips($('#main'),cs);$('#main').scrollTop=0}\nasync function showFile(path){\n  cur={kind:'file',key:path,path:path,name:path};\n  var f=await api('GET','/api/file?path='+encodeURIComponent(path));\n  var h='<h1 class=\"t\">'+esc(path)+'</h1><div><span class=\"tag\">'+esc(f.lang)+'</span><span class=\"tag\">'+f.lines+' 行</span>'+(f.note_stale?'<span class=\"tag\" style=\"color:var(--er)\">說明可能過期</span>':'')+'</div>';\n  h+=f.note?'<div class=\"note\"><b>說明</b>（'+esc(f.note_by||'AI')+'）：'+noteHtml(f.note)+' <a class=\"l\" id=\"editnote\">編輯</a></div>':'<div class=\"mut\">還沒有說明。<a class=\"l\" id=\"editnote\">自己補一段</a>，或請 AI 讀過後補。</div>';\n  if(f.doc)h+='<p>'+esc(f.doc)+'</p>';\n  var cs=[['這個檔案是做什麼的','這個檔案（'+path+'）是做什麼的'],['__explain__','__explain__'],['誰引用它','誰用到 '+path],['它引用了什麼','這個檔案（'+path+'）依賴哪些檔案'],['請 AI 讀過後解釋','請讀 '+path+'，解釋它的用途、主要流程與要注意的地方','ai'],['請 AI 補說明（存進資料庫）','__dive__','ai']];\n  h+=chips(cs)+'<div><button id=\"src\">看程式碼</button> <button id=\"expl\">行為說明（可折疊）</button></div><div id=\"srcbox\"></div><div id=\"explbox\" class=\"md\"></div>';\n  h+='<h2>定義（'+f.symbols.length+'）</h2>'+(f.symbols.length?'<table>'+f.symbols.map(function(s){return '<tr><td>'+slink(s.n)+'</td><td><span class=\"tag\">'+esc(s.k)+'</span></td><td>第 '+s.l+' 行</td><td>'+(s.note?noteFold(s.note):'')+(s.d?esc(s.d)+'<br>':'')+(s.sig?'<code>'+esc(s.sig)+'</code>':'')+'</td></tr>'}).join('')+'</table>':'<div class=\"mut\">（沒有抽到定義）</div>');\n  h+='<h2>引用了誰（'+f.imports.length+'）</h2>'+(f.imports.map(function(p){return '<div>'+link(p)+'</div>'}).join('')||'<div class=\"mut\">（沒有）</div>');\n  h+='<h2>被誰引用（'+f.imported_by.length+'）</h2>'+(f.imported_by.map(function(p){return '<div>'+link(p)+'</div>'}).join('')||'<div class=\"mut\">（沒有）</div>');\n  $('#main').innerHTML=h;$('#main').scrollTop=0;\n  $('#main').querySelectorAll('.chips span').forEach(function(sp){if(cs[+sp.dataset.ci][0]==='__explain__')sp.textContent='這個檔案在做什麼（行為說明）';sp.onclick=async function(){var c=cs[+sp.dataset.ci];if(c[1]==='__explain__'){document.getElementById('expl').click();return}if(c[1]==='__dive__'){try{var r=await api('POST','/api/dive',{path:path});addMsg('a ai','AI','<span class=\"mut\">⏳ 已排進佇列：讀過 '+esc(path)+' 後補說明（'+(r.queue_pos>1?'前面還有 '+(r.queue_pos-1)+' 個':'馬上開始')+'）</span>')}catch(e){addMsg('a','錯誤','<span class=\"err\">'+esc(e.message)+'</span>')}}else ask(c[1],cur,c[2]==='ai')}});\n  $('#expl').onclick=async function(){var b=$('#expl');b.disabled=true;$('#explbox').innerHTML='<span class=\"mut\">分析中…</span>';try{var r=await api('GET','/api/explain?path='+encodeURIComponent(path));$('#explbox').innerHTML=mdToHtml(r.markdown)+(r.unclassified&&r.unclassified.length?'<div class=\"mut\">還不認得的呼叫：'+r.unclassified.slice(0,20).map(function(u){return esc(u&&typeof u==='object'?u.name:u)}).join('、')+'（可請 AI 讀過後用 behavior_define 補定義）</div>':'')}catch(e){$('#explbox').innerHTML='<span class=\"err\">'+esc(e.message)+'</span>'}b.disabled=false};\n  $('#editnote').onclick=function(){if($('#main .mde'))return;var nb=$('#main').querySelector('.note')||$('#editnote').parentNode;var ed=mdEditor({title:'編輯檔案說明：'+path,value:f.note||'',onSave:function(v,bx){saveNote(cur,v);bx.remove()}});nb.parentNode.insertBefore(ed,nb.nextSibling)};\n  $('#src').onclick=async function(){var b=$('#src');b.disabled=true;try{var s=await api('GET','/api/source?path='+encodeURIComponent(path)+'&from=1&to=200');$('#srcbox').innerHTML='<pre>'+esc(s.text)+'</pre>'+(s.total>s.to?'<div class=\"mut\">只顯示前 '+s.to+' 行（共 '+s.total+' 行）</div>':'')}catch(e){$('#srcbox').innerHTML='<span class=\"err\">'+esc(e.message)+'</span>'}};\n}\nasync function showDir(path,tr){\n  cur={kind:'dir',key:path,path:path,name:path};\n  var h='<h1 class=\"t\">'+esc(path)+'/</h1><div><span class=\"tag\">資料夾</span><span class=\"tag\">'+tr.dirs.length+' 個子資料夾</span><span class=\"tag\">'+tr.files.length+' 個檔案'+(tr.more?'（另有 '+tr.more+' 項沒列出）':'')+'</span></div>';\n  h+=tr.note?'<div class=\"note\"><b>說明</b>：'+noteHtml(tr.note)+'</div>':'<div class=\"mut\">這個資料夾還沒有說明。</div>';\n  var cs=[['這個資料夾是做什麼的','這個資料夾（'+path+'）是做什麼的'],['請 AI 讀過後解釋','請看 '+path+' 底下的檔案，用白話說明這個資料夾的用途、主要檔案與它們的關係','ai']];\n  h+=chips(cs);\n  if(tr.dirs.length)h+='<h2>子資料夾</h2>'+tr.dirs.map(function(d){return '<div><a class=\"l\" data-go=\"dir:'+esc(path+'/'+d)+'\">'+esc(d)+'/</a></div>'}).join('');\n  if(tr.files.length)h+='<h2>檔案</h2>'+tr.files.map(function(f){return '<div>'+link(path+'/'+f.name)+(f.note?' <span class=\"k\">✎</span>':'')+'</div>'}).join('');\n  $('#main').innerHTML=h;wireChips($('#main'),cs);$('#main').scrollTop=0;\n}\nasync function showSym(name){\n  cur={kind:'symbol',key:name,path:'',name:name};\n  var r=await api('GET','/api/symbol?name='+encodeURIComponent(name)),via='';\n  if(!r.defs.length){\n    var tr=null;try{tr=await api('GET','/api/tree?path='+encodeURIComponent(name))}catch(e){}\n    if(tr&&tr.exists){showDir(name.replace(/\\/+$/,''),tr);return}\nvar tail=String(name).split(/[.:]+|->|#/).filter(Boolean).pop()||name,hits=[];\n    if(tail&&tail!==name){var alt=null;try{alt=await api('GET','/api/symbol?name='+encodeURIComponent(tail))}catch(e){}\n      if(alt&&alt.defs&&alt.defs.length){r=alt;via='<div class=\"mut\" style=\"margin-bottom:6px\">「'+esc(name)+'」本身不在索引裡，用最後一段「'+esc(tail)+'」查到：</div>';name=tail}}\n    if(!r.defs.length){navFail('索引裡沒有');\n    try{hits=((await api('GET','/api/search?q='+encodeURIComponent(tail))).hits||[]).filter(function(x){return x.type==='symbol'&&String(x.name).split(/[.:]+/).pop().toLowerCase()===String(tail).toLowerCase()})}catch(e){}\n      var mh='<div class=\"note\"><b>索引裡沒有「'+esc(name)+'」的定義。</b><br>常見原因：它是<b>繼承或覆寫</b>來的（例如 C# 的 <code>InitializeComponent</code> 在 .Designer.cs 的 partial class 裡，<code>OnPaint</code> 這類來自框架的父類別），或來自沒有建索引的函式庫，或這個檔案還沒被分析到。這不是你的專案壞了。</div>'+\n        '<div style=\"margin:8px 0\"><button class=\"nvb\" data-nav=\"back\"'+(NAV.i>0?'':' disabled')+'>◀ 回到上一個位置</button> <button class=\"nvb\" onclick=\"document.getElementById(\\'navH\\').click()\">🕘 看瀏覽歷史</button></div>';\n      if(hits.length)mh+='<h2>名字相同的其他定義（'+hits.length+'，不一定是同一個）</h2>'+hits.slice(0,30).map(function(x){return '<div><a class=\"l\" data-go=\"sym:'+esc(x.name)+'\">'+esc(x.name)+'</a> <span class=\"k\">'+esc(x.kind)+' · '+esc(x.path)+':'+x.line+'</span></div>'}).join('');\n      else mh+='<div class=\"mut\">專案裡沒有任何名叫「'+esc(tail)+'」的定義。</div>';\n      $('#main').innerHTML=mh;return}\n  }\n  cur.path=r.defs[0].path;\n  var h=via+'<h1 class=\"t\">'+esc(name)+'</h1><div class=\"mut\">'+r.defs.length+' 個定義</div>';\n  var cs=[[name+' 是做什麼的',name+' 是做什麼的'],['誰用到 '+name,'誰用到 '+name],[name+' 相關的東西',name+' 相關的東西'],['請 AI 深入解釋','請讀 '+r.defs[0].path+' 裡的 '+name+'，解釋它做什麼、參數與回傳、何時會被呼叫、要注意什麼','ai']];\n  r.defs.slice(0,10).forEach(function(d){\n    h+='<h2>'+esc(d.kind)+'　'+locLink(d.path,d.line,'',esc(d.path+':'+d.line))+'</h2>';\n    h+='<div><a class=\"l\" data-editsym=\"'+esc(d.path)+'|'+esc(name)+'\">'+(d.note?'編輯':'補')+'這個定義的說明</a></div>';\n    h+=d.note?'<div class=\"note\"><b>說明</b>（'+esc(d.note_by||'AI')+(d.stale?'，可能過期':'')+'）：'+noteHtml(d.note)+'</div>':(d.doc?'':'<div class=\"mut\">還沒有說明。</div>');\n    if(d.doc)h+='<p>'+esc(d.doc)+'</p>';\n    if(d.sig)h+='<pre>'+esc(d.sig)+'</pre>';\n    if(d.users&&d.users.length)h+='<div><b>被這些檔案使用（'+d.users.length+'）：</b> '+d.users.slice(0,20).map(function(p){return link(p)}).join('、')+'</div>';\n    if(d.same&&d.same.length)h+='<div style=\"margin-top:4px\"><b>同檔案的其他定義：</b> '+d.same.map(slink).join('、')+'</div>';\n  });\n  h+=chips(cs);$('#main').innerHTML=h;wireChips($('#main'),cs);$('#main').scrollTop=0;\n}\nfunction goRaw(g){var i=g.indexOf(':'),k=g.slice(0,i),v=g.slice(i+1);var p=k==='file'?showFile(v):(k==='dir'?api('GET','/api/tree?path='+encodeURIComponent(v)).then(function(tr){return showDir(v,tr)}):k==='sym'?showSym(v):(k==='page'?showPage(v):null));if(p&&p.catch)p.catch(function(e){$('#main').innerHTML='<div class=\"note\">'+esc(e.message)+'</div>';navFail(e.message)});return p}\n\n/* ===== 瀏覽歷史：上一個／下一個位置＋歷史清單（像 call stack）。連到壞掉的連結也會留在歷史裡（標紅），隨時可以退回去 ===== */\nvar NAV={st:[],i:-1,max:200};\nfunction navScroller(){return document.querySelector('.pane.on .main')||document.getElementById('main')}\nfunction navSave(){var e=NAV.st[NAV.i],sc=navScroller();if(e&&sc)e.sy=sc.scrollTop}\nfunction navText(g){var i=g.indexOf(':'),k=g.slice(0,i),v=g.slice(i+1);return (k==='file'?'📄 ':k==='sym'?'ƒ ':(k==='dir'||k==='folder')?'📁 ':k==='page'?'📖 ':'• ')+(k==='file'?v.split('/').slice(-2).join('/'):v)}\nfunction navPush(g){navSave();var top=NAV.st[NAV.i];if(top&&top.g===g){navRender();return}NAV.st.length=NAV.i+1;NAV.st.push({g:g,t:navText(g),fail:''});if(NAV.st.length>NAV.max)NAV.st.shift();NAV.i=NAV.st.length-1;navRender()}\nfunction navFail(why){var e=NAV.st[NAV.i];if(e){e.fail=why||'失敗';navRender()}}\nfunction navTo(i){if(i<0||i>=NAV.st.length)return;navSave();NAV.i=i;var e=NAV.st[i],sy=e.sy||0;e.fail='';navRender();var rs=function(){var sc=navScroller();if(sc)sc.scrollTop=sy};Promise.resolve(goRaw(e.g)).then(function(){setTimeout(rs,0);setTimeout(rs,250)},function(){});setTimeout(rs,60)} /* 每一筆記得捲動位置：退回去時回到原本看到的地方 */\nfunction navBack(){navTo(NAV.i-1)}function navFwd(){navTo(NAV.i+1)}\nfunction navRender(){\n  var b=document.getElementById('navB'),f=document.getElementById('navF');if(b)b.disabled=NAV.i<=0;if(f)f.disabled=NAV.i>=NAV.st.length-1;\n  var p=document.getElementById('navp');if(!p||p.style.display==='none')return;\n  var h='<div class=\"nh\"><b>瀏覽歷史（'+NAV.st.length+'）　最新在上</b><a data-navclear=\"1\" style=\"padding:0 6px;display:inline\">清除</a></div>';\n  for(var k=NAV.st.length-1;k>=0;k--){var e=NAV.st[k];h+='<a data-navi=\"'+k+'\" class=\"'+(k===NAV.i?'cur ':'')+(e.fail?'fail':'')+'\" title=\"'+esc(e.fail||e.g)+'\"><span class=\"ix\">'+(k+1)+'</span><span>'+esc(e.t)+(e.fail?' ⚠ '+esc(e.fail):'')+'</span><span style=\"margin-left:auto;color:var(--mut);font-size:11px;white-space:nowrap\">'+(k===NAV.i?'目前':(k>NAV.i?'下一個位置':''))+'</span></a>'}\n  p.innerHTML=h}\n(function(){var p=document.createElement('div');p.id='navp';document.body.appendChild(p);\n  document.getElementById('navB').onclick=navBack;document.getElementById('navF').onclick=navFwd;\n  document.getElementById('navH').onclick=function(e){e.stopPropagation();p.style.display=p.style.display==='block'?'none':'block';navRender()};\n  p.addEventListener('click',function(e){e.stopPropagation();var c=e.target.closest('[data-navclear]');if(c){var cur=NAV.st[NAV.i];NAV.st=cur?[cur]:[];NAV.i=cur?0:-1;navRender();return}var a=e.target.closest('[data-navi]');if(a){p.style.display='none';navTo(+a.getAttribute('data-navi'))}});\n  document.addEventListener('click',function(e){if(!e.target.closest('#navp'))p.style.display='none'});\n  document.addEventListener('keydown',function(e){if(e.altKey&&e.key==='ArrowLeft'){e.preventDefault();navBack()}else if(e.altKey&&e.key==='ArrowRight'){e.preventDefault();navFwd()}else if(e.key==='Escape')p.style.display='none'});\n  document.addEventListener('mouseup',function(e){if(e.button===3){e.preventDefault();navBack()}else if(e.button===4){e.preventDefault();navFwd()}});\n  document.addEventListener('click',function(e){var a=e.target.closest('[data-nav]');if(a){e.preventDefault();if(a.getAttribute('data-nav')==='back')navBack();else navFwd()}})})();\nfunction go(g){navPush(g);goRaw(g)}\nfunction refreshCur(){if(cur.kind==='file')showFile(cur.key);else if(cur.kind==='symbol')showSym(cur.key);else if(cur.kind==='page')showPage(cur.key);if(tab==='notes')renderList()}\ndocument.addEventListener('click',function(e){var es=e.target.closest('[data-editsym]');if(es){e.preventDefault();var pp=es.getAttribute('data-editsym').split('|');var host=es.parentNode;if(host.nextElementSibling&&host.nextElementSibling.classList.contains('mde'))return;api('GET','/api/symbol?name='+encodeURIComponent(pp[1])).then(function(r){var d=r.defs.filter(function(x){return x.path===pp[0]})[0]||{};var ed=mdEditor({title:'編輯說明：'+pp[1],value:d.note||'',onSave:function(v,bx){saveNote({path:pp[0],kind:'symbol',name:pp[1]},v);bx.remove()}});host.parentNode.insertBefore(ed,host.nextSibling)});return}var lc=e.target.closest('[data-loc]');if(lc){e.preventDefault();toggleLoc(lc);return}var a=e.target.closest('[data-go]');if(a){e.preventDefault();go(a.getAttribute('data-go'))}});\ndocument.querySelectorAll('#tabs button').forEach(function(b){b.onclick=function(){tab=b.dataset.t;document.querySelectorAll('#tabs button').forEach(function(x){x.classList.toggle('on',x===b)});$('#sq').value='';renderList()}});\nvar sqT=null;$('#sq').oninput=function(){clearTimeout(sqT);sqT=setTimeout(renderList,250)};\n$('#ask').onclick=function(){var v=$('#q').value;$('#q').value='';ask(v,cur,false)};\n$('#askai').onclick=function(){var v=$('#q').value;$('#q').value='';ask(v,cur,true)};\n$('#q').onkeydown=function(e){if(e.key==='Enter'){var v=$('#q').value;$('#q').value='';ask(v,cur,e.shiftKey)}};\n$('#btnNet').onclick=function(){var d=$('#net');d.open=!d.open};\n// ---- 版面：左／中／右可拖曳調整、左右可隱藏、右邊可停靠右／左／下；偏好由主程式保存（iframe 沒有自己的儲存空間） ----\nvar DEF={dock:'right',navW:270,chatW:360,chatH:0,navHidden:false,chatHidden:false},PREF=Object.assign({},DEF),prefT=null;\nfunction applyPref(){\n  var app=$('#app'),root=document.documentElement.style;app.className='dock-'+PREF.dock;\n  document.body.classList.toggle('hide-nav',!!PREF.navHidden);document.body.classList.toggle('hide-chat',!!PREF.chatHidden);\n  root.setProperty('--navw',PREF.navW+'px');root.setProperty('--chatw',PREF.chatW+'px');if(PREF.chatH>0)root.setProperty('--chath',PREF.chatH+'px');else root.removeProperty('--chath');\n  $('#dockSel').value=PREF.dock;$('#btnNav').classList.toggle('off',!!PREF.navHidden);$('#btnChat').classList.toggle('off',!!PREF.chatHidden);\n}\nfunction savePref(){clearTimeout(prefT);prefT=setTimeout(function(){api('POST','/api/prefs',{layout:PREF}).catch(function(){})},300)}\nfunction setPref(k,v){PREF[k]=v;applyPref();savePref()}\nasync function loadPrefs(){try{var r=await api('GET','/api/prefs');if(r&&r.layout)Object.assign(PREF,r.layout)}catch(e){}applyPref()}\nfunction clampN(v,lo,hi){return Math.max(lo,Math.min(hi,v))}\nfunction dragSplit(sp,onMove,onDbl){\n  sp.addEventListener('pointerdown',function(e){e.preventDefault();var sx=e.clientX,sy=e.clientY,nav=$('#nav').offsetWidth,chat=$('#chat').offsetWidth,chh=$('#chat').offsetHeight;sp.classList.add('drag');try{sp.setPointerCapture(e.pointerId)}catch(_){}\n    var mv=function(ev){onMove(ev.clientX-sx,ev.clientY-sy,{nav:nav,chat:chat,chh:chh})};\n    var up=function(){sp.classList.remove('drag');sp.removeEventListener('pointermove',mv);sp.removeEventListener('pointerup',up);savePref()};\n    sp.addEventListener('pointermove',mv);sp.addEventListener('pointerup',up)});\n  sp.addEventListener('dblclick',onDbl);\n}\ndragSplit($('#spL'),function(dx,dy,s){PREF.navW=clampN(s.nav+dx,120,Math.max(160,innerWidth-260));applyPref()},function(){setPref('navW',DEF.navW)});\ndragSplit($('#spR'),function(dx,dy,s){\n  if(PREF.dock==='bottom')PREF.chatH=clampN(s.chh-dy,80,Math.max(120,innerHeight-160));\n  else PREF.chatW=clampN(s.chat+(PREF.dock==='left'?dx:-dx),200,Math.max(240,innerWidth-260));\n  applyPref()},function(){PREF.chatW=DEF.chatW;PREF.chatH=0;applyPref();savePref()});\n$('#btnNav').onclick=function(){setPref('navHidden',!PREF.navHidden)};\n$('#btnChat').onclick=function(){setPref('chatHidden',!PREF.chatHidden)};\n$('#dockSel').onchange=function(){PREF.dock=$('#dockSel').value;applyPref();savePref()};\n$('#btnReset').onclick=async function(){try{var r=await api('POST','/api/prefs',{reset:true});PREF=Object.assign({},DEF,r&&r.layout||{})}catch(e){PREF=Object.assign({},DEF)}applyPref()};\n(async function(){\n  try{await loadPrefs();setInfo(await api('GET','/api/info'));setJobs((await api('GET','/api/jobs')).jobs);await renderList();var p=await api('GET','/api/pages');if(p.pages.length){navPush('page:'+p.pages[0].id);showPage(p.pages[0].id)}else $('#main').innerHTML='<h1 class=\"t\">'+esc(CFG.title)+'</h1><div class=\"mut\">左邊可以瀏覽檔案與定義；右邊直接問問題。點任何檔案或函式，下面的小按鈕可以請離線問答或 AI 說明它。</div>'}\n  catch(e){$('#main').innerHTML='<div class=\"note err\">載入失敗：'+esc(e.message)+'</div>'}\n  connect();\n})();\n})();\n</script>\n</body></html>\n";
