            const fname = lang === 'python' ? 'test_' + (FILTERS.snake(cname) || 'use_case') : (lang === 'typescript' ? cname + '.test' : cname + 'Test'); const dir = lang === 'java' ? L.testDir + '/' + pkg.replace(/\./g, '/') : L.testDir;
