const FA_CATALOG_PROBE_PY = "# 單元目錄的探測執行（只用標準庫；在 Pyodide 或一般 CPython 裡都能跑）。設計見 DESIGN.unit-catalog.md 第四、五節。\n# 只對「純函式」（模組白名單、沒有副作用）執行，並且：\n#   - 用稽核掛鉤（sys.addaudithook）擋下檔案、網路、子行程、程式碼執行這類事件，碰到就中止那一次呼叫、記成 blocked；\n#   - 每個案例執行兩次，結果不同就標非決定性；結果與輸出都截短；\n#   - 逾時由呼叫端（JS）終止整個 Worker，這裡只負責不讓單次結果太大。\n# 用法：JS 端把 PROBE_REQ 那一行的占位符換成請求（JSON 字串的字面值）再執行；輸出一行 \"FA_PROBE_RESULT:\" + JSON。\n#   請求：{\"jobs\":[{\"id\",\"module\",\"name\",\"cases\":[{\"args\":[...],\"kwargs\":{...}}]}], \"max_repr\":200}\n#   參數值的特殊編碼：{\"$bytes\": \"<base64>\"}→ bytes；{\"$tuple\": [...]}→ tuple。\nimport sys, json, importlib, base64, math, re\n\nREQ = json.loads(__FA_PROBE_REQ__)\nMAX_REPR = int(REQ.get('max_repr', 200))\nMAX_JSON = int(REQ.get('max_json', 2000))  # 正式執行時結果可以大一點\nBLOCKED_EVENTS = {'open', 'os.system', 'os.exec', 'os.posix_spawn', 'os.spawn', 'os.fork', 'os.forkpty', 'subprocess.Popen', 'os.remove', 'os.rename', 'os.rmdir', 'os.mkdir',\n                  'os.chmod', 'os.chown', 'os.truncate', 'os.symlink', 'os.link', 'os.putenv', 'os.unsetenv', 'shutil.rmtree', 'shutil.copyfile', 'shutil.move', 'shutil.copytree',\n                  'ctypes.dlopen', 'ctypes.dlsym', 'exec', 'compile', 'import.__main__', 'webbrowser.open', 'tempfile.mkstemp', 'tempfile.mkdtemp', 'urllib.Request', 'http.client.connect'}\n_state = {'armed': False}\n\n\ndef _hook(event, args):\n    if not _state['armed']:\n        return\n    if event in BLOCKED_EVENTS or event.startswith('socket.') or event.startswith('subprocess.'):\n        raise RuntimeError('blocked:' + event)\n\n\ntry:\n    sys.addaudithook(_hook)\n    AUDIT = True\nexcept Exception:  # 沒有稽核掛鉤（很舊的版本）：不執行任何探測，直接回報\n    AUDIT = False\n\n\ndef decode(v):\n    if isinstance(v, dict):\n        if '$bytes' in v and len(v) == 1:\n            return base64.b64decode(v['$bytes'])\n        if '$tuple' in v and len(v) == 1:\n            return tuple(decode(x) for x in v['$tuple'])\n        return {k: decode(x) for k, x in v.items()}\n    if isinstance(v, list):\n        return [decode(x) for x in v]\n    return v\n\n\ndef tname(v, depth=0):\n    # 結果值 → 我們的型別詞彙（對不上的一律 any，不猜）\n    if v is None:\n        return 'null'\n    if isinstance(v, bool):\n        return 'bool'\n    if isinstance(v, int):\n        return 'int'\n    if isinstance(v, (float, complex)):\n        return 'number'\n    if type(v).__name__ in ('Fraction', 'Decimal'):\n        return 'number'\n    if isinstance(v, str):\n        return 'text'\n    if isinstance(v, (bytes, bytearray)):\n        return 'bytes'\n    if isinstance(v, dict):\n        return 'dict'\n    if isinstance(v, (list, tuple, set, frozenset)):\n        if depth >= 2:\n            return 'list<any>'\n        items = list(v)[:20]\n        if not items:\n            return 'list<any>'\n        ts = sorted(set(tname(x, depth + 1) for x in items))\n        if 'number' in ts and 'int' in ts:\n            ts.remove('int')\n        return 'list<' + (ts[0] if len(ts) == 1 else 'union<' + '|'.join(ts) + '>') + '>'\n    return 'any'\n\n\ndef srepr(v):\n    # 物件的預設 repr 帶記憶體位址（每次不同），比較與記錄時去掉，不然會被誤判成非決定性\n    return re.sub(r' (at|@) 0x[0-9a-fA-F]+', '', repr(v))\n\n\ndef jsonable(v):\n    try:\n        s = json.dumps(v, allow_nan=False)\n        return json.loads(s) if len(s) <= MAX_JSON else None\n    except Exception:\n        return None\n\n\ndef one_call(fn, case):\n    args = [decode(a) for a in case.get('args', [])]\n    kwargs = {k: decode(v) for k, v in (case.get('kwargs') or {}).items()}\n    _state['armed'] = True\n    try:\n        return fn(*args, **kwargs)\n    finally:\n        _state['armed'] = False\n\n\ndef run_case(fn, case):\n    positional = False\n    try:\n        try:\n            r1 = one_call(fn, case)\n        except TypeError as e:\n            # 存根寫成關鍵字參數、實際是僅位置參數（例如 math.log）：改用位置參數重試一次，並記下來\n            if 'keyword argument' in str(e) and case.get('kwargs'):\n                r1 = one_call(fn, {'args': list(case.get('args', [])) + list(case['kwargs'].values()), 'kwargs': {}})\n                positional = True\n            else:\n                raise\n    except RuntimeError as e:\n        if str(e).startswith('blocked:'):\n            return {'ok': False, 'exc': 'Blocked', 'msg': str(e)[:120], 'blocked': True}\n        return {'ok': False, 'exc': 'RuntimeError', 'msg': str(e)[:120]}\n    except BaseException as e:  # 包含 SystemExit：探測不能讓整個程序結束\n        return {'ok': False, 'exc': type(e).__name__, 'msg': str(e)[:120], 'bases': [c.__name__ for c in type(e).__mro__[1:4]]}\n    if REQ.get('once'):  # 正式執行（不是探測）：只呼叫一次，不做「兩次結果相同」的檢查\n        det = True\n    else:\n        try:\n            r2 = one_call(fn, {'args': list(case.get('args', [])) + list(case['kwargs'].values()), 'kwargs': {}} if positional else case)\n            det = srepr(r1) == srepr(r2)\n        except BaseException:\n            det = False\n    j = jsonable(r1)\n    out = {'ok': True, 'type': tname(r1), 'repr': srepr(r1)[:MAX_REPR], 'det': det, 'jsonable': j is not None or r1 is None}\n    if positional:\n        out['positional'] = True\n    if out['jsonable']:\n        out['json'] = j\n    if isinstance(r1, float) and (math.isnan(r1) or math.isinf(r1)):\n        out['jsonable'] = False\n        out.pop('json', None)\n    return out\n\n\nres = {'ok': True, 'python': sys.version.split()[0], 'audit': AUDIT, 'jobs': []}\nfor job in REQ.get('jobs', []):\n    item = {'id': job['id'], 'cases': [], 'import_error': None}\n    if not AUDIT:\n        item['import_error'] = 'no audit hook'\n        res['jobs'].append(item)\n        continue\n    try:\n        mod = importlib.import_module(job['module'])\n        fn = mod\n        for part in job['name'].split('.'):\n            fn = getattr(fn, part)\n        if not callable(fn):\n            raise TypeError('not callable')\n    except BaseException as e:\n        item['import_error'] = type(e).__name__ + ': ' + str(e)[:120]\n        res['jobs'].append(item)\n        continue\n    for case in job.get('cases', []):\n        item['cases'].append(run_case(fn, case))\n    res['jobs'].append(item)\nprint('FA_PROBE_RESULT:' + json.dumps(res, ensure_ascii=False))\n";
/* CATPROBEPY-END */
/* CATEVALSET-BEGIN */
const FA_CATALOG_EVAL_SET_JSON = "{\n  \"version\": 1,\n  \"note\": \"單元選擇評測集：需求 → 標準答案單元（可多個等價的）。neg＝清單裡不該有任何適合的（該回 0）。python 單元需要先 /unit-catalog onboard 這些模組。作者手寫，答案由人判斷；有爭議的題目已盡量改成沒有歧義的說法。\",\n  \"modules\": [\"statistics\", \"math\", \"json\", \"string\", \"textwrap\", \"base64\", \"hashlib\", \"zlib\", \"html\", \"urllib.parse\", \"operator\", \"fnmatch\", \"shlex\", \"difflib\", \"posixpath\"],\n  \"cases\": [\n    { \"id\": \"p01\", \"query\": \"算這一串數字的平均值\", \"truth\": [\"py:statistics.mean\"] },\n    { \"id\": \"p02\", \"query\": \"找出一組數字的中位數\", \"truth\": [\"py:statistics.median\"] },\n    { \"id\": \"p03\", \"query\": \"計算這些數值的樣本標準差\", \"truth\": [\"py:statistics.stdev\"] },\n    { \"id\": \"p04\", \"query\": \"哪個數字在清單裡出現最多次\", \"truth\": [\"py:statistics.mode\"] },\n    { \"id\": \"p05\", \"query\": \"求 144 的平方根\", \"truth\": [\"py:math.sqrt\"] },\n    { \"id\": \"p06\", \"query\": \"計算 10 的階乘\", \"truth\": [\"py:math.factorial\"] },\n    { \"id\": \"p07\", \"query\": \"兩個整數的最大公因數\", \"truth\": [\"py:math.gcd\"] },\n    { \"id\": \"p08\", \"query\": \"把小數無條件進位成整數\", \"truth\": [\"py:math.ceil\"] },\n    { \"id\": \"p09\", \"query\": \"把小數無條件捨去成整數\", \"truth\": [\"py:math.floor\"] },\n    { \"id\": \"p10\", \"query\": \"算以 10 為底的對數\", \"truth\": [\"py:math.log10\"] },\n    { \"id\": \"p11\", \"query\": \"把 JSON 字串轉成資料結構\", \"truth\": [\"py:json.loads\"] },\n    { \"id\": \"p12\", \"query\": \"把資料結構轉成 JSON 文字\", \"truth\": [\"py:json.dumps\"] },\n    { \"id\": \"p13\", \"query\": \"把資料做 base64 編碼\", \"truth\": [\"py:base64.b64encode\"] },\n    { \"id\": \"p14\", \"query\": \"把 base64 字串解回原始資料\", \"truth\": [\"py:base64.b64decode\"] },\n    { \"id\": \"p15\", \"query\": \"算一段文字的 SHA-256 雜湊值\", \"truth\": [\"py:hashlib.sha256\"] },\n    { \"id\": \"p16\", \"query\": \"算一段資料的 MD5 雜湊值\", \"truth\": [\"py:hashlib.md5\"] },\n    { \"id\": \"p17\", \"query\": \"用 zlib 壓縮一段位元組資料\", \"truth\": [\"py:zlib.compress\"] },\n    { \"id\": \"p18\", \"query\": \"解壓縮 zlib 壓縮過的資料\", \"truth\": [\"py:zlib.decompress\"] },\n    { \"id\": \"p19\", \"query\": \"把文字做 URL 編碼（百分比編碼）\", \"truth\": [\"py:urllib.parse.quote\"] },\n    { \"id\": \"p20\", \"query\": \"把 URL 編碼過的文字還原\", \"truth\": [\"py:urllib.parse.unquote\"] },\n    { \"id\": \"p21\", \"query\": \"把網址拆成協定、主機、路徑這些部分\", \"truth\": [\"py:urllib.parse.urlparse\"] },\n    { \"id\": \"p22\", \"query\": \"把一段長文字依指定寬度自動換行\", \"truth\": [\"py:textwrap.fill\"] },\n    { \"id\": \"p23\", \"query\": \"移除多行文字共同的縮排\", \"truth\": [\"py:textwrap.dedent\"] },\n    { \"id\": \"p24\", \"query\": \"把字串裡的 HTML 特殊字元跳脫\", \"truth\": [\"py:html.escape\"] },\n    { \"id\": \"p25\", \"query\": \"把 &amp; 這類 HTML 實體還原成原本的字元\", \"truth\": [\"py:html.unescape\"] },\n    { \"id\": \"p26\", \"query\": \"把命令列字串切成參數清單\", \"truth\": [\"py:shlex.split\"] },\n    { \"id\": \"p27\", \"query\": \"把每個單字的第一個字母大寫\", \"truth\": [\"py:string.capwords\"] },\n    { \"id\": \"p28\", \"query\": \"檢查檔名是不是符合 *.txt 這種萬用字元樣式\", \"truth\": [\"py:fnmatch.fnmatch\"] },\n    { \"id\": \"p29\", \"query\": \"從一份清單裡找出跟輸入最接近的字串\", \"truth\": [\"py:difflib.get_close_matches\"] },\n    { \"id\": \"p30\", \"query\": \"把幾段路徑片段接成一個路徑\", \"truth\": [\"py:posixpath.join\"] },\n    { \"id\": \"p31\", \"query\": \"取出路徑最後面的檔名\", \"truth\": [\"py:posixpath.basename\"] },\n    { \"id\": \"p32\", \"query\": \"把檔名跟副檔名分開\", \"truth\": [\"py:posixpath.splitext\"] },\n    { \"id\": \"p33\", \"query\": \"取出路徑裡資料夾的部分\", \"truth\": [\"py:posixpath.dirname\"] },\n    { \"id\": \"t01\", \"query\": \"把這幾張圖片合成一個 PDF\", \"truth\": [\"tool:images_to_pdf\"] },\n    { \"id\": \"t02\", \"query\": \"把兩份 PDF 合併成一份\", \"truth\": [\"tool:merge_pdfs\"] },\n    { \"id\": \"t03\", \"query\": \"只取出 PDF 的第 3 到第 5 頁\", \"truth\": [\"tool:extract_pdf_pages\"] },\n    { \"id\": \"t04\", \"query\": \"刪掉 PDF 的第一頁\", \"truth\": [\"tool:remove_pdf_pages\"] },\n    { \"id\": \"t05\", \"query\": \"把影片裡的聲音抽成 MP3\", \"truth\": [\"tool:extract_audio\"] },\n    { \"id\": \"t06\", \"query\": \"把這段錄音轉成逐字稿\", \"truth\": [\"tool:transcribe_media\"] },\n    { \"id\": \"t07\", \"query\": \"把字幕燒進影片裡\", \"truth\": [\"tool:burn_subtitles\"] },\n    { \"id\": \"t08\", \"query\": \"把影片轉成動態 GIF\", \"truth\": [\"tool:convert_to_animated_gif\"] },\n    { \"id\": \"t09\", \"query\": \"把這段文字念成語音\", \"truth\": [\"tool:text_to_speech\"] },\n    { \"id\": \"t10\", \"query\": \"把這個網址的網頁內容抓下來\", \"truth\": [\"tool:fetch_web_page\"] },\n    { \"id\": \"t11\", \"query\": \"上網搜尋最新的 AI 新聞\", \"truth\": [\"tool:browser_search\"] },\n    { \"id\": \"t12\", \"query\": \"看這張圖片，告訴我裡面有什麼\", \"truth\": [\"tool:interpret_image\"] },\n    { \"id\": \"t13\", \"query\": \"比較兩張圖片有什麼不同\", \"truth\": [\"tool:compare_images\"] },\n    { \"id\": \"t14\", \"query\": \"讀取我電腦上某個檔案的內容\", \"truth\": [\"tool:fs_read_file\"] },\n    { \"id\": \"t15\", \"query\": \"列出某個資料夾裡有哪些檔案\", \"truth\": [\"tool:fs_list_files\"] },\n    { \"id\": \"t16\", \"query\": \"用 Python 寫一小段程式跑起來算結果\", \"truth\": [\"tool:python_execute\"] },\n    { \"id\": \"t17\", \"query\": \"把這份資料畫成長條圖\", \"truth\": [\"tool:render_chart\"] },\n    { \"id\": \"t18\", \"query\": \"把這篇很長的文章摘要成幾句話\", \"truth\": [\"tool:summarize_large_text\"] },\n    { \"id\": \"t19\", \"query\": \"下載這支 YouTube 影片\", \"truth\": [\"tool:youtube_download\"] },\n    { \"id\": \"t20\", \"query\": \"看目前 git 倉庫有哪些檔案被改動\", \"truth\": [\"tool:git_status\"] },\n    { \"id\": \"t21\", \"query\": \"擷取影片第 10 秒的畫面存成圖片\", \"truth\": [\"tool:extract_video_frames\"] },\n    { \"id\": \"n01\", \"kind\": \"neg\", \"query\": \"幫我訂明天到台北的高鐵票\", \"truth\": [] },\n    { \"id\": \"n02\", \"kind\": \"neg\", \"query\": \"今天台北的天氣怎麼樣\", \"truth\": [] },\n    { \"id\": \"n03\", \"kind\": \"neg\", \"query\": \"幫我寄一封電子郵件給我的主管\", \"truth\": [] },\n    { \"id\": \"n04\", \"kind\": \"neg\", \"query\": \"把客廳的冷氣調到 26 度\", \"truth\": [] },\n    { \"id\": \"n05\", \"kind\": \"neg\", \"query\": \"播放周杰倫的歌\", \"truth\": [] },\n    { \"id\": \"n06\", \"kind\": \"neg\", \"query\": \"幫我叫一輛計程車到機場\", \"truth\": [] },\n    { \"id\": \"n07\", \"kind\": \"neg\", \"query\": \"預約下週三下午的牙醫門診\", \"truth\": [] },\n    { \"id\": \"n08\", \"kind\": \"neg\", \"query\": \"幫我轉帳五千元給小明\", \"truth\": [] }\n  ],\n  \"args\": [\n    { \"unit\": \"py:statistics.mean\", \"query\": \"算 3、5、8、10 的平均值\", \"expected\": { \"data\": [3, 5, 8, 10] } },\n    { \"unit\": \"py:math.sqrt\", \"query\": \"求 144 的平方根\", \"expected\": { \"x\": 144 } },\n    { \"unit\": \"py:math.log10\", \"query\": \"算 1000 以 10 為底的對數\", \"expected\": { \"x\": 1000 } },\n    { \"unit\": \"py:math.gcd\", \"query\": \"求 12 和 18 的最大公因數\", \"expected\": { \"args\": [12, 18] }, \"skipIfNoParams\": true },\n    { \"unit\": \"py:base64.b64encode\", \"query\": \"把 hello 做 base64 編碼\", \"expected\": { \"s\": \"hello\" } },\n    { \"unit\": \"py:hashlib.sha256\", \"query\": \"算字串 abc 的 SHA-256\", \"expected\": { \"string\": \"abc\" } },\n    { \"unit\": \"py:urllib.parse.quote\", \"query\": \"把「你好 世界」做 URL 編碼\", \"expected\": { \"string\": \"你好 世界\" } },\n    { \"unit\": \"py:textwrap.fill\", \"query\": \"把「The quick brown fox jumps over the lazy dog」每行寬度 20 換行\", \"expected\": { \"text\": \"The quick brown fox jumps over the lazy dog\", \"width\": 20 } },\n    { \"unit\": \"py:html.escape\", \"query\": \"把 <b>hi</b> 跳脫成 HTML 安全的文字\", \"expected\": { \"s\": \"<b>hi</b>\" } },\n    { \"unit\": \"py:posixpath.basename\", \"query\": \"取出 /home/user/notes/todo.txt 的檔名\", \"expected\": { \"p\": \"/home/user/notes/todo.txt\" } },\n    { \"unit\": \"py:string.capwords\", \"query\": \"把「hello big world」每個字首字母大寫\", \"expected\": { \"s\": \"hello big world\" } },\n    { \"unit\": \"py:math.factorial\", \"query\": \"算 7 的階乘\", \"expected\": { \"x\": 7 } },\n    { \"unit\": \"tool:fetch_web_page\", \"query\": \"抓 https://example.com/news 的內容\", \"expected\": { \"url\": \"https://example.com/news\" } },\n    { \"unit\": \"tool:text_to_speech\", \"query\": \"把「你好，歡迎使用」念成語音\", \"expected\": { \"text\": \"你好，歡迎使用\" } },\n    { \"unit\": \"tool:browser_search\", \"query\": \"搜尋「最新 AI 新聞」\", \"expected\": { \"query\": \"最新 AI 新聞\" } },\n    { \"unit\": \"tool:fs_read_file\", \"query\": \"讀取 C:/notes/todo.txt\", \"expected\": { \"path\": \"C:/notes/todo.txt\" } },\n    { \"unit\": \"tool:fs_list_files\", \"query\": \"列出 D:/projects 資料夾裡的檔案\", \"expected\": { \"path\": \"D:/projects\" } },\n    { \"unit\": \"tool:interpret_image\", \"query\": \"描述 file_id 是 abc123 的這張圖\", \"expected\": { \"file_id\": \"abc123\" } }\n  ],\n  \"intents\": {\n    \"py:statistics.mean\": \"計算平均值\",\n    \"py:statistics.median\": \"計算中位數\",\n    \"py:statistics.stdev\": \"計算樣本標準差\",\n    \"py:statistics.mode\": \"找出出現最多次的值（眾數）\",\n    \"py:math.sqrt\": \"計算平方根\",\n    \"py:math.factorial\": \"計算階乘\",\n    \"py:math.gcd\": \"計算最大公因數\",\n    \"py:math.ceil\": \"無條件進位\",\n    \"py:math.floor\": \"無條件捨去\",\n    \"py:math.log10\": \"計算以 10 為底的對數\",\n    \"py:json.loads\": \"JSON 字串轉成資料結構\",\n    \"py:json.dumps\": \"資料結構轉成 JSON 文字\",\n    \"py:base64.b64encode\": \"base64 編碼\",\n    \"py:base64.b64decode\": \"base64 解碼\",\n    \"py:hashlib.sha256\": \"計算 SHA-256 雜湊\",\n    \"py:hashlib.md5\": \"計算 MD5 雜湊\",\n    \"py:zlib.compress\": \"zlib 壓縮\",\n    \"py:zlib.decompress\": \"zlib 解壓縮\",\n    \"py:urllib.parse.quote\": \"URL 編碼（百分比編碼）\",\n    \"py:urllib.parse.unquote\": \"URL 解碼\",\n    \"py:urllib.parse.urlparse\": \"把網址拆成各部分\",\n    \"py:textwrap.fill\": \"依寬度自動換行\",\n    \"py:textwrap.dedent\": \"移除共同縮排\",\n    \"py:html.escape\": \"HTML 跳脫\",\n    \"py:html.unescape\": \"HTML 實體還原\",\n    \"py:shlex.split\": \"切分命令列字串\",\n    \"py:string.capwords\": \"每個單字首字母大寫\",\n    \"py:fnmatch.fnmatch\": \"檔名萬用字元比對\",\n    \"py:difflib.get_close_matches\": \"找最接近的字串\",\n    \"py:posixpath.join\": \"接合路徑\",\n    \"py:posixpath.basename\": \"取路徑的檔名\",\n    \"py:posixpath.splitext\": \"分離檔名與副檔名\",\n    \"py:posixpath.dirname\": \"取路徑的資料夾部分\"\n  }\n}\n";
