const FA_CATALOG_INTENTS_JSON = "{\n \"py:statistics.mean\": \"計算平均值\",\n \"py:statistics.median\": \"計算中位數\",\n \"py:statistics.stdev\": \"計算樣本標準差\",\n \"py:statistics.mode\": \"找出出現最多次的值（眾數）\",\n \"py:math.sqrt\": \"計算平方根\",\n \"py:math.factorial\": \"計算階乘\",\n \"py:math.gcd\": \"計算最大公因數\",\n \"py:math.ceil\": \"無條件進位\",\n \"py:math.floor\": \"無條件捨去\",\n \"py:math.log10\": \"計算以 10 為底的對數\",\n \"py:json.loads\": \"JSON 字串轉成資料結構\",\n \"py:json.dumps\": \"資料結構轉成 JSON 文字\",\n \"py:base64.b64encode\": \"base64 編碼\",\n \"py:base64.b64decode\": \"base64 解碼\",\n \"py:hashlib.sha256\": \"計算 SHA-256 雜湊\",\n \"py:hashlib.md5\": \"計算 MD5 雜湊\",\n \"py:zlib.compress\": \"zlib 壓縮\",\n \"py:zlib.decompress\": \"zlib 解壓縮\",\n \"py:urllib.parse.quote\": \"URL 編碼（百分比編碼）\",\n \"py:urllib.parse.unquote\": \"URL 解碼\",\n \"py:urllib.parse.urlparse\": \"把網址拆成各部分\",\n \"py:textwrap.fill\": \"依寬度自動換行\",\n \"py:textwrap.dedent\": \"移除共同縮排\",\n \"py:html.escape\": \"HTML 跳脫\",\n \"py:html.unescape\": \"HTML 實體還原\",\n \"py:shlex.split\": \"切分命令列字串\",\n \"py:string.capwords\": \"每個單字首字母大寫\",\n \"py:fnmatch.fnmatch\": \"檔名萬用字元比對\",\n \"py:difflib.get_close_matches\": \"找最接近的字串\",\n \"py:posixpath.join\": \"接合路徑\",\n \"py:posixpath.basename\": \"取路徑的檔名\",\n \"py:posixpath.splitext\": \"分離檔名與副檔名\",\n \"py:posixpath.dirname\": \"取路徑的資料夾部分\",\n \"tool:add_chapters\": \"簡報分批寫：把一批章節加進草稿\",\n \"tool:begin_presentation\": \"開始做一份很長的簡報（分好幾批寫、最後合成一份）\",\n \"tool:define_snippet\": \"存一段很長的文字給簡報用，換成短代號，不用塞進 YAML\",\n \"tool:finish_presentation\": \"把簡報草稿的每一批合成一份完整簡報、檢查並存檔\",\n \"tool:get_presentation_topic\": \"查簡報格式的規則：版型、投影片欄位、轉場、視覺\",\n \"tool:get_presentation_yaml\": \"取得已存的簡報 YAML 內容（用檔案代號或網址）\",\n \"tool:import_fap_image\": \"把使用者授權資料夾裡的圖片檔帶進這個任務\",\n \"tool:import_image_url\": \"從網頁下載一張圖片帶進任務\",\n \"tool:list_source_images\": \"列出這個任務裡看過的所有圖片（上傳的、截圖、網頁下載的）\",\n \"tool:open_existing_presentation\": \"打開之前存好的簡報來看或修改\",\n \"tool:pptx_to_deck\": \"把使用者上傳的 PowerPoint 檔轉成簡報描述\",\n \"tool:render_chart\": \"畫圖表：長條圖、折線圖、圓餅圖，把資料畫成圖片\",\n \"tool:render_presentation\": \"檢查簡報描述（YAML）並存成簡報檔、算簡報\",\n \"py:statistics.correlation\": \"算兩組數字的相關係數 皮爾森相關\",\n \"py:statistics.covariance\": \"算兩組數字的共變異數\",\n \"py:statistics.fmean\": \"算平均值（浮點數，比較快）\",\n \"py:statistics.geometric_mean\": \"算幾何平均數 成長率平均\",\n \"py:statistics.harmonic_mean\": \"算調和平均數\",\n \"py:statistics.median_grouped\": \"算分組資料的中位數\",\n \"py:statistics.median_high\": \"取偏高的中位數（偶數個時取較大那個）\",\n \"py:statistics.median_low\": \"取偏低的中位數（偶數個時取較小那個）\",\n \"py:statistics.multimode\": \"找出出現最多次的值（可能有好幾個）眾數\",\n \"py:statistics.pstdev\": \"算母體標準差\",\n \"py:statistics.pvariance\": \"算母體變異數\",\n \"py:statistics.quantiles\": \"把資料切成相同機率的區間 分位數 四分位數\",\n \"py:statistics.variance\": \"算樣本變異數\",\n \"py:math.acos\": \"反餘弦 算角度（弧度）\",\n \"py:math.acosh\": \"反雙曲餘弦\",\n \"py:math.asin\": \"反正弦 算角度（弧度）\",\n \"py:math.asinh\": \"反雙曲正弦\",\n \"py:math.atan\": \"反正切 算角度（弧度）\",\n \"py:math.atan2\": \"由 y 和 x 算角度（弧度） 方位角\",\n \"py:math.atanh\": \"反雙曲正切\",\n \"py:math.cbrt\": \"算立方根 開三次方\",\n \"py:math.comb\": \"算組合數 從 n 個選 k 個有幾種選法\",\n \"py:math.copysign\": \"取一個數的大小、配上另一個數的正負號\",\n \"py:math.cos\": \"算餘弦\",\n \"py:math.cosh\": \"雙曲餘弦\",\n \"py:math.degrees\": \"弧度轉角度\",\n \"py:math.dist\": \"算兩點之間的歐氏距離\",\n \"py:math.erf\": \"誤差函數\",\n \"py:math.erfc\": \"互補誤差函數\",\n \"py:math.exp\": \"算 e 的 x 次方 指數\",\n \"py:math.exp2\": \"算 2 的 x 次方\",\n \"py:math.expm1\": \"算 e 的 x 次方減 1（小數字比較準）\",\n \"py:math.fabs\": \"取絕對值（浮點數）\",\n \"py:math.fma\": \"乘加合併運算 x 乘 y 再加 z\",\n \"py:math.fmod\": \"取餘數（浮點數，依 C 語言規則）\",\n \"py:math.frexp\": \"把數字拆成尾數和指數\",\n \"py:math.fsum\": \"精確加總一串浮點數 加總\",\n \"py:math.gamma\": \"伽瑪函數 階乘的推廣\",\n \"py:math.hypot\": \"算多維的歐氏長度 斜邊長 向量長度\",\n \"py:math.isclose\": \"判斷兩個浮點數是不是差不多相等\",\n \"py:math.isfinite\": \"判斷數字是不是有限（不是無限大也不是 NaN）\",\n \"py:math.isinf\": \"判斷是不是正負無限大\",\n \"py:math.isnan\": \"判斷是不是 NaN（不是數字）\",\n \"py:math.isqrt\": \"算整數平方根（只取整數部分）\",\n \"py:math.lcm\": \"算最小公倍數\",\n \"py:math.ldexp\": \"算 x 乘 2 的 i 次方\",\n \"py:math.lgamma\": \"伽瑪函數絕對值的自然對數\",\n \"py:math.log1p\": \"算 1 加 x 的自然對數（小數字比較準）\",\n \"py:math.log2\": \"算以 2 為底的對數\",\n \"py:math.modf\": \"把數字拆成小數部分和整數部分\",\n \"py:math.nextafter\": \"取下一個浮點數（往指定方向）\",\n \"py:math.perm\": \"算排列數 從 n 個排 k 個有幾種排法\",\n \"py:math.pow\": \"算次方 x 的 y 次方\",\n \"py:math.prod\": \"把一串數字全部相乘 連乘\",\n \"py:math.radians\": \"角度轉弧度\",\n \"py:math.remainder\": \"算 IEEE 規則的餘數（與 y 最近倍數的差）\",\n \"py:math.sin\": \"算正弦\",\n \"py:math.sinh\": \"雙曲正弦\",\n \"py:math.sumprod\": \"兩組數字對應相乘再加總 內積\",\n \"py:math.tan\": \"算正切\",\n \"py:math.tanh\": \"雙曲正切\",\n \"py:math.ulp\": \"取浮點數最小的位元單位 精度\",\n \"py:textwrap.wrap\": \"把一段長文字依寬度折成多行 自動換行\",\n \"py:textwrap.shorten\": \"把文字縮短到指定寬度（太長就截斷加省略）\",\n \"py:base64.encodebytes\": \"把位元組編成多行 base64 文字\",\n \"py:base64.b32encode\": \"base32 編碼\",\n \"py:base64.b32hexencode\": \"base32hex 編碼\",\n \"py:base64.b16encode\": \"base16 編碼 轉十六進位文字\",\n \"py:base64.b85encode\": \"base85 編碼\",\n \"py:base64.b85decode\": \"base85 解碼\",\n \"py:base64.a85encode\": \"Ascii85 編碼\",\n \"py:base64.a85decode\": \"Ascii85 解碼\",\n \"py:base64.z85encode\": \"z85 編碼\",\n \"py:base64.z85decode\": \"z85 解碼\",\n \"py:base64.standard_b64encode\": \"標準 base64 編碼\",\n \"py:base64.urlsafe_b64encode\": \"網址安全的 base64 編碼\",\n \"py:zlib.adler32\": \"算 Adler-32 校驗碼\",\n \"py:zlib.crc32\": \"算 CRC-32 校驗碼 檢查資料有沒有壞\",\n \"py:urllib.parse.urljoin\": \"把基底網址和相對網址組成完整網址 網址相加\",\n \"py:urllib.parse.urldefrag\": \"移除網址最後的 # 片段\",\n \"py:urllib.parse.urlsplit\": \"把網址拆成協定、主機、路徑、查詢、片段 解析網址\",\n \"py:urllib.parse.parse_qs\": \"解析網址查詢字串 取出參數（每個參數是清單）\",\n \"py:urllib.parse.parse_qsl\": \"解析網址查詢字串 取出參數（成對的清單）\",\n \"py:urllib.parse.quote_plus\": \"網址編碼（空白變加號）\",\n \"py:urllib.parse.quote_from_bytes\": \"把位元組做網址編碼\",\n \"py:urllib.parse.unquote_plus\": \"網址解碼（加號變空白）\",\n \"py:urllib.parse.unquote_to_bytes\": \"網址解碼成位元組\",\n \"py:operator.abs\": \"取絕對值\",\n \"py:operator.concat\": \"把兩個序列接在一起 串接\",\n \"py:operator.index\": \"轉成整數索引\",\n \"py:fnmatch.fnmatchcase\": \"判斷檔名符不符合萬用字元樣式（分大小寫）\",\n \"py:fnmatch.translate\": \"把萬用字元樣式轉成正規表示式\",\n \"py:shlex.quote\": \"把字串變成 shell 安全的字串 加跳脫引號\",\n \"py:shlex.join\": \"把一串參數組成 shell 命令字串\",\n \"py:difflib.restore\": \"從差異結果還原出其中一份原始內容\",\n \"py:difflib.IS_CHARACTER_JUNK\": \"判斷字元是不是可忽略的（空白或 tab）\",\n \"py:posixpath.isabs\": \"判斷路徑是不是絕對路徑\",\n \"py:posixpath.commonprefix\": \"找出多個路徑最長的共同開頭\",\n \"py:posixpath.islink\": \"判斷路徑是不是符號連結\",\n \"py:posixpath.exists\": \"判斷路徑存不存在\",\n \"py:posixpath.lexists\": \"判斷路徑存不存在（符號連結本身也算）\",\n \"py:posixpath.isfile\": \"判斷路徑是不是一般檔案\",\n \"py:posixpath.ismount\": \"判斷路徑是不是掛載點\",\n \"py:posixpath.expanduser\": \"展開路徑裡的 ~ 家目錄\",\n \"py:posixpath.expandvars\": \"展開路徑裡的環境變數\",\n \"py:posixpath.normpath\": \"整理路徑 去掉多餘的斜線和 ..\",\n \"py:posixpath.abspath\": \"把路徑變成絕對路徑\",\n \"py:posixpath.sameopenfile\": \"判斷兩個打開的檔案是不是同一個檔案\",\n \"py:posixpath.realpath\": \"取得路徑的真實位置（解開符號連結）\",\n \"py:posixpath.isjunction\": \"判斷路徑是不是 Windows 連接點\",\n \"py:posixpath.isdevdrive\": \"判斷路徑是不是在 Windows 開發磁碟機上\"\n}\n";
