        const neg = NEG.test(t); if (neg && !sc.expectation) add('observation', 2, '壞掉的狀態');
        if (neg && /(?:不應|不該|不得|不會再|不再|不要|should not|shouldn'?t|must not|no longer|never)/i.test(t)) add('expectation', 4, '「不應該…」');
