                try { const i = await opts.pick('這一句是什麼角色？「' + sg.text.slice(0, 80) + '」', c.options.slice(0, 4)); if (Number.isInteger(i) && i >= 0 && i < Math.min(4, c.options.length)) { role = c.options[i]; by = 'model'; } } catch (_) { /* 用程式的第一名 */ }
