    const toNum = (v) => { if (isNum(v)) return v; if (typeof v === 'string' && /^\s*-?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:e[+-]?\d+)?\s*$/i.test(v)) return Number(v.replace(/,/g, '')); return null; };
