        const cByWord = new Map(); for (const h of vals.contains.filter((x) => scopeIds.has(x.t.id) && !used.some(([a, b]) => x.span[0] < b && x.span[1] > a))) { const k = h.value.toLowerCase(); if (!cByWord.has(k)) cByWord.set(k, []); cByWord.get(k).push(h); }
