    // ---------- lint ----------
    const SECRET_RES = [/(?:password|passwd|secret|token|api[_-]?key|access[_-]?key)\s*[=:]\s*['"]?[A-Za-z0-9/+_=.-]{12,}/i, /AKIA[0-9A-Z]{16}/, /gh[pousr]_[A-Za-z0-9]{30,}/, /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/, /xox[baprs]-[A-Za-z0-9-]{10,}/];
