            if (lang === 'python' && (text.startsWith('"""', i) || text.startsWith("'''", i))) { const q = text.slice(i, i + 3); let j = text.indexOf(q, i + 3); if (j < 0) j = n - 3; comments.push({ start: i, end: j + 3, text: text.slice(i + 3, j).replace(/\s+/g, ' ').trim(), doc: true }); blank(i, j + 3); i = j + 3; continue; }
            let j = i + 1;
