                catch (e) { const msg = String((e && e.message) || e); if (cur.cancelled) { modal.close(); st.textContent = '已取消'; } else { modal.fail(msg); st.textContent = '❌ ' + msg.slice(0, 80); st.style.color = '#f87171'; } }
