                    const r = await this._deckImportImageBlob(new Blob([f.svg], { type: 'image/svg+xml' }), 'cute: ' + f.name, 'cute_picture');
                    return r.error ? r : { ok: true, name: f.name, zhuyin: f.zhuyin, ref: r.ref, url: r.url };
