                    bud.left--; this._kiEmit({ op: 'images', text: '🖼 讀網頁圖片 ' + (bud.used + bud.failed + 1) + '：' + file });
                    const r = await this._kiVisionImage(blob.type ? blob : new Blob([blob], { type: 'image/jpeg' }), '網頁圖片' + (alt ? '，替代文字：' + alt : '') + '：' + file);
