            tr.log('離線流程沒解出來：' + (h._offlineLastNote || '沒有對應的規則').slice(0, 160) + '，改走反思');
            const rf = await this.reflect(task, body, tr, intentR);
            if (rf && rf.text) { tr.done('給出達成路線'); return { response: this.textResponse(body, rf.text), model: 'offline' }; }
