                pages: { type: 'array', description: '（選填）每頁一個物件，順序＝頁序；要逐頁不同的旋轉／縮放／處理時用', items: { type: 'object', properties: {
                    file: { type: 'string', description: 'file_id、檔名、fap:名稱/路徑 或 桌面版絕對路徑' }, rotate: { type: 'number', description: '順時針角度（90、-90、180、15…）' }, scale: { type: 'number', description: '圖片像素縮放百分比（50＝縮成一半）' },
                    ops: { type: 'array', items: { type: 'object' }, description: '只作用這一頁的處理（接在全部頁面共用的ops後面）' }, zoom: { type: 'number' }, fit: { type: 'string' }, page_size: { type: 'string' }, orientation: { type: 'string' }, margin: { type: 'number' }, background: { type: 'string' } }, required: ['file'] } },
                folder: { type: 'string', description: '（選填）整個資料夾的圖片：fap:名稱/路徑，或桌面版絕對路徑，依檔名自然排序' },
                pattern: { type: 'string', description: '（選填）folder的檔名篩選，例如 "*.jpg"' },
                sort: { type: 'string', enum: ['none', 'name', 'name_desc', 'modified', 'reverse'], description: '（選填）排序：預設——有給files/pages＝照給的順序，folder／附件＝依檔名自然排序' },
                ops: { type: 'array', items: { type: 'object', properties: { op: { type: 'string', enum: ['grayscale', 'enhance', 'tone', 'reduce_colors', 'blur', 'mosaic', 'sharpen', 'auto_contrast', 'brightness', 'contrast', 'saturation', 'gamma', 'threshold', 'posterize', 'invert', 'rotate', 'scale', 'crop', 'flip'] } }, required: ['op'], additionalProperties: true }, description: '（選填）所有頁面共用的處理，依序執行，例如 [{"op":"enhance"},{"op":"grayscale"}]' },
                page_size: { type: 'string', description: '（選填）fit（預設）／a3／a4／a5／b5／letter／legal／"210x297mm"' },
