                const num = (v, lo, hi) => { const n = Math.floor(Number(v)); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : null; };
                const args = ['/work/in/input.png', '--out', '/work/out', '--vision', vision];
                const ms = num(parsed.max_side, 64, 1024); if (ms) args.push('--max-side', String(ms));
