        if (!st || (!st.sql && !st.db.files.length)) return { ok: false, error: '這個專案還沒有索引，先 /aidoc index' };
        const live = this._wgLive && this._wgLive.get('aidoc_' + key);
        const reused = !!(live && live.node && live.node.isConnected);
