        const tokenize = (seg) => { const out = []; const re = /"([^"]*)"|'([^']*)'|(\S+)/g; let m; while ((m = re.exec(seg))) out.push(m[1] != null ? m[1] : (m[2] != null ? m[2] : m[3])); return out; };
        const writeArgs = async (script, rest) => { const f = rpc + '/args.json'; await window.desktopAPI.rawfs.writeFile(f, { text: JSON.stringify({ script, args: rest }) }); return f; };
        if (hasScriptArgs) {
            const all = args.map(String);
            if (all.some((x) => NONASCII.test(x))) { const f = await writeArgs(all[0], all.slice(1)); return { command: cmd, args: [runner, '--rpc', rpc, '--argsfile', f], runId, rpc }; }
            return { command: cmd, args: [runner, '--rpc', rpc, '--'].concat(all), runId, rpc };
        }
