        let body; if (a.b64) { const bin = atob(a.b64); const u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); body = u; }
        const method = String(a.method || 'GET').toUpperCase();
