            const sink = { path: '', onOpen() { st.open = true; done(); }, onMessage(d) { st.queue.push(d); }, onClose(code, reason) { st.closed = { code: code || 1005, reason: reason || '' }; done(); }, onReject(r) { st.error = String(r || '被伺服器拒絕'); done(); } };
