        const eng = FaBeh2.create({ patterns: FA_BEHAVIOR_DATA.patterns, api: FA_BEHAVIOR_DATA.api }, this._behTsHost(), this._behV2User(lang === 'asm' || lang === 'cpp' ? 'c' : lang, aidocNotes));
        const notes = {}; if (fileNote) notes[path] = fileNote;
