            if (src.assembly_idioms) for (const [a, list] of Object.entries(src.assembly_idioms)) { u.idioms[a] = (list || []).concat(u.idioms[a] || []); added.idioms += (list || []).length; }
            if (src.idioms) for (const [a, list] of Object.entries(src.idioms)) { u.idioms[a] = (list || []).concat(u.idioms[a] || []); added.idioms += (list || []).length; }
