        const extra = await this._codeExportCollect(key, map); const exportId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
        const parts = []; let notes = null, total = 0; let viewerName = 'viewer.html';
        const manifestBase = { v: 1, exportId, created: Date.now(), root: key, index: 'index.sqlite3' };
        const title = '專案百科：' + (key.split('/').filter(Boolean).pop() || key);
        const counts = (await (await this._idxConn(key)).R.counts()) || {};
        const stats = { files: counts.files || 0, symbols: counts.symbols || 0, imports: counts.imports || 0, uses: counts.uses || 0 };
        const a = await this._sqliteWasmAssets(); const [mjs, wasm] = await Promise.all([this._gzB64(new TextEncoder().encode(a.js)), this._gzB64(a.wasm)]);
        const cfg = { mode: 'parts', title, root: key, generated: Date.now(), stats, complete: !!map.index_built, sql: { gz: { js: mjs.gz, wasm: wasm.gz } }, notesDdl: (typeof FaIdxSql !== 'undefined' && FaIdxSql.NOTES_DDL) || [], exportId };
        let ai = null; if (opts.ai !== false) { try { ai = await this._codeAiPack(); } catch (_) { ai = null; } } if (ai) { cfg.ai = ai.cfg; cfg.aiGz = ai.gz; }
