            await raw.remove(pdir, true); await raw.mkdir(pdir); report('複製索引資料庫…');
            const r = await raw.copyChunked(dir + '/index.sqlite3', pdir + '/db-', PART); parts.push(...r.parts); total = r.size;
            try { const n = await raw.copyChunked(dir + '/notes.sqlite3', pdir + '/notes.sqlite3'); notes = { name: 'notes.sqlite3', size: n.size }; } catch (_) { notes = null; }
            await raw.writeFile(pdir + '/' + viewerName, { text: html });
