        this._amSet((c) => { Object.keys(D.assign).forEach((m) => Object.keys(D.assign[m]).forEach((st) => { if (c.modes[m] && c.modes[m].stages[st]) { kept++; return; } if (D.assign[m][st].prefs.length) { A.setPrefs(c, m, st, D.assign[m][st].prefs); n++; } })); });
