        if (this._intentLogged !== text) { this._intentLogged = text; this._log('🎯 意圖過濾：根層級 ' + all.length + ' 個工具 → 送 ' + names.length + ' 個（' + names.filter((n) => ALWAYS.indexOf(n) < 0).slice(0, 8).join('、') + (names.length > 8 ? '…' : '') + '），其餘 ' + hidden.length + ' 個只列名稱'); }
