                    + lab('開頭說明（選填）') + '<input data-k="lead" style="' + inp + '" value="' + esc(t.lead) + '">' + lab('章節（每行一個）') + '<textarea data-k="sections" rows="6" style="' + inp + '; font-family:Consolas,monospace;">' + esc((t.sections || []).join('\n')) + '</textarea>';
