        const useTr = a.translate === true || (a.translate !== false && !!this.advancedSettings.offlineMode);
        const translate = useTr ? async (t, to) => { try { const r = await this.translateText({ text: t, to, engine: this.advancedSettings.offlineMode ? 'offline' : 'auto' }); return r && r.ok && r.engine !== 'none' ? r.text : null; } catch (_) { return null; } } : null;
