                this._skillAutoRecipes[b.id] = res.ok ? Object.assign({}, res.recipe, { id: ('r_' + b.id.replace(/[^a-z0-9]/gi, '').slice(0, 20)).toLowerCase(), skillId: b.id, sig, info: { description: info.description } }) : { sig, status: 'none' };
