                const a = await this.requestUserForm({ title: '🧩 要安裝並學習新的函式庫嗎？', description: O.confirmText(req), choices: ['允許安裝', '取消'] });
                if (!a || !a.confirmed || a.answer !== '允許安裝') return { ok: false, stage: 'confirm', error: '使用者沒有同意安裝，沒有做任何事。' };
