                if (fresh.length) { const prev = this._refEngine().findTyped('text_lexicon', 'user-words'); const all = Array.from(new Set(((prev && prev.customize && prev.customize.words) || []).concat(fresh))); const rr = await this._refDefine({ kind: 'text_lexicon', key: 'user-words', text: '使用者標註時補的字詞', tags: ['text', 'en', 'user'], customize: { lang: 'en', words: all }, source: 'user（標註）' }); if (rr.ok) notes.push('詞庫新增 ' + fresh.length + ' 個字'); }
