                // _normalizeAdvancedSettings的同一個決策，維持三處一致）。
                const raw = perfMaxMeshTrianglesInput.value.trim();
                if (raw !== '') {
                    const n = Number(raw);
                    if (Number.isFinite(n) && n >= 0) this.advancedSettings.maxImportedMeshTriangles = Math.round(n);
                }
